(window.EX_CHUNKS=window.EX_CHUNKS||{})["b08"]={"流利":[["他的英语说得非常流利。","ئۇنىڭ ئىنگلىز تىلى ئىنتايىن راۋان.","uning ingliz tili intayin rawan."]],"挥霍":[["他挥霍无度，很快就花光了积蓄。","ئۇ ئىسراپچىلىق بىلەن پۇل سەرپ قىلىپ، پات ئارىدا پۇل-مېلىنى تۈگەتتى.","u israpchiliq bilen pul serp qilip, pat arida pul-mélini tügetti."]],"咈":[["他“咈咈”地笑。","ئۇ «فۇفۇ» دەپ كۈلدى.","u «fufu» dep küldi."]],"惈":[["面对失败，他并未感到惈然。","مەغلۇبىيەتكە دۇچ كەلگەندە، ئۇ ھەرگىز ئۈمىدسىزلىككە چۆكمىدى.","meghlubiyetke duch kelgende, u hergiz ümidsizlikke chökmidi."]],"穈":[["穈米具有独特的香气。","سېرىق تارىق ئۆزگىچە خۇش پۇراققا ئىگە.","sériq tariq özgiche xush puraqqa ige."]],"砈":[["这砈很锋利。","بۇ تاش بەك ئۆتكۈر.","bu tash bek ötkür."]],"筈":[["筈字在古籍中常见。","«كۇ» دېگەن خەت قەدىمكى كىتابلاردا كۆپ ئۇچرايدۇ.","«ku» dégen xet qedimki kitablarda köp uchraydu."]],"蜈":[["蜈蚣有很多对足，行动迅速。","چىياننىڭ پۇتلىرى كۆپ بولۇپ، ھەرىكىتى چاققاندۇر.","chiyanning putliri köp bolup, herikiti chaqqandur."]],"螈":[["蝾螈可以在水中呼吸。","سۇ كەلتىرىسى سۇدا نەپەس ئالالايدۇ.","su keltirisi suda nepes alalaydu."]],"鳈":[["鳈鱼通常成群结队地游动。","چۈەن بېلىقى ئادەتتە توپ-توپ بولۇپ ئۈزىدۇ.","chüen béliqi adette top-top bolup üzidu."]],"鯈":[["鯈鱼的颜色鲜艳夺目。","يالتىراق بېلىقنىڭ رەڭگى پارقىراپ كۆزنى چاقىلىتىدۇ.","yaltiraq béliqning renggi parqirap közni chaqilitidu."]],"齈":[["这种齈虫对皮肤有害。","بۇ خىل قۇرت تېرىگە زىيانلىق.","bu xil qurt térige ziyanliq."]],"一个劲":[["他一个劲地夸我做得好。","ئۇ مېنىڭ ياخشى قىلغانلىقىمنى توختىماي ماختاپ كەتتى.","u méning yaxshi qilghanliqimni toxtimay maxtap ketti."]],"一字儿":[["他说话总爱加个‘儿’音，比如‘一字儿’。","ئۇ سۆزلىگەندە ھەمىشە «ئېر» ئاۋازىنى قوشۇپ سۆزلەيدۇ، مەسىلەن «بىر خەتئېر».","u sözligende hemishe «ér» awazini qoshup sözleydu, mesilen «bir xet'ér»."]],"一炮打响":[["他的表演一炮打响，广受好评。","ئۇنىڭ ئويۇنى بىرلا قېتىملىق مۇۋەپپەقىيەت قازىنىپ، كەڭ ئالقىشقا ئېرىشتى.","uning oyuni birla qétimliq muweppeqiyet qazinip, keng alqishqa érishti."]],"一无所动":[["他对此诱惑一无所动，坚守原则。","ئۇ بۇ ئازدۇرۇشقا ھەرگىز ئېتىبار بەرمەي، پرىنسىپىدا چىڭ تۇردى.","u bu azdurushqa hergiz étibar bermey, prinsipida ching turdi."]],"一丝一毫":[["不要浪费一丝一毫的机会。","بىر تالچىلىقمۇ پۇرسەتنى ئىسراپ قىلماڭ.","bir talchiliqmu pursetni israp qilmang."]],"一时瑜亮":[["两人堪称一时瑜亮。","ئىككىيلەننى بىر زاماننىڭ يۈلياڭ-جوڭياڭى دېيىشكە بولىدۇ.","ikkiylenni bir zamanning yülyang-jongyangi déyishke bolidu."]],"一月":[["一月是今年的第一个月份。","يانۋار بۇ يىلنىڭ بىرىنچى ئېيى.","yanwar bu yilning birinchi éyi."]],"一胎化":[["他们推行了一胎化政策。","ئۇلار بىر بالىلىق سىياسىتىنى ئىلگىرى سۈردى.","ular bir baliliq siyasitini ilgiri sürdi."]],"一叶障目":[["一叶障目，不见泰山。","بىر ياپراق كۆزنى توسسا، تەيشان تېغىنى كۆرگىلى بولمايدۇ.","bir yapraq közni tossa, teyshan téghini körgili bolmaydu."]],"一览":[["可以一览全景。","پۈتۈن مەنزىرىنى بىر قاراشتا كۆرگىلى بولىدۇ.","pütün menzirini bir qarashta körgili bolidu."]],"一言既出，驷马难追":[["一言既出，驷马难追，必须遵守承诺。","بىر ئېغىز سۆز ئېيتىلغاندىن كېيىن، تۆت ئات قوغلىسىمۇ يېتەلمەيدۇ، ۋەدىگە چوقۇم ئەمەل قىلىش كېرەك.","bir éghiz söz éytilghandin kéyin, töt at qoghlisimu yételmeydu, wedige choqum emel qilish kérek."]],"七武士":[["《七武士》是一部经典的日本电影。","«يەتتە سامۇراي» كلاسسىك ياپونىيە فىلىمى.","«yette samuray» klassik yaponiye filimi."]],"不学无术":[["他完全不学无术。","ئۇ پۈتۈنلەي ئوقۇمسىز، ھېچقانداق بىلىمى يوق.","u pütünley oqumsiz, héchqandaq bilimi yoq."]],"下关":[["下关是历史名城。","شياگۇەن تارىخىي مەشھۇر شەھەردۇر.","shyaguen tarixiy meshhur sheherdur."]],"不得劲":[["今天感觉特别不得劲。","بۈگۈن ئۆزىنى ئالاھىدە بىئارام ھېس قىلىۋاتىدۇ.","bügün özini alahide biaram hés qiliwatidu."]],"上蔡县":[["上蔡县历史悠久。","تەرجىمە قىلىنغان جۈملىلەر:","terjime qilinghan jümliler:"]],"不饱和":[["这种油含有大量不饱和脂肪酸。","بۇ خىل ياغدا كۆپ مىقداردا تويۇنمىغان ياغ كىسلاتاسى بار.","bu xil yaghda köp miqdarda toyunmighan yagh kislatasi bar."]],"不饱和脂肪酸":[["不饱和脂肪酸对心脏健康有益。","تويۇنمىغان ياغ كىسلاتاسى يۈرەك ساغلاملىقىغا پايدىلىق.","toyunmighan yagh kislatasi yürek saghlamliqigha paydiliq."]],"不首先使用":[["该国承诺不首先使用核武器。","بۇ دۆلەت يادرو قورالىنى ئالدى بىلەن ئىشلەتمەسلىككە ۋەدە بەردى.","bu dölet yadro qoralini aldi bilen ishletmeslikke wede berdi."]],"且末县":[["且末县位于新疆南部。","چەرچەن ناھىيىسى شىنجاڭنىڭ جەنۇبىدا جايلاشقان.","cherchen nahiyisi shinjangning jenubida jaylashqan."]],"不灵":[["这个机器今天怎么这么不灵？","بۇ ماشىنا بۈگۈن نېمىشقا بۇنچە ئىشلىمەيدۇ؟","bu mashina bügün némishqa bunche ishlimeydu?"]],"中国航海日":[["中国航海日旨在弘扬航海文化。","جۇڭگو دېڭىز سەپىرى كۈنى دېڭىز سەپىرى مەدەنىيىتىنى تەرغىب قىلىشنى مەقسەت قىلىدۇ.","junggo déngiz sepiri küni déngiz sepiri medeniyitini terghib qilishni meqset qilidu."]],"中法":[["中法两国签署了合作协议。","جۇڭگو بىلەن فرانسىيە ئىككى دۆلەت ھەمكارلىق كېلىشىمى ئىمزالادى.","junggo bilen fransiye ikki dölet hemkarliq kélishimi imzaladi."]],"中兴新村":[["中兴新村是一个历史悠久的地方。","جۇڭشىڭ يېڭى كەنتى ئۇزۇن تارىخقا ئىگە بىر جاي.","jungshing yéngi kenti uzun tarixqa ige bir jay."]],"中西区":[["中西区是城市的中心。","جۇڭگو-غەرب رايونى شەھەرنىڭ مەركىزىدۇر.","junggo-gherb rayoni sheherning merkizidur."]],"中山狼传":[["《中山狼传》是一篇古代寓言故事。","«جۇڭشەن بۆرىسى ھەققىدە ھېكايە» قەدىمكى زامان ۋەقەلىك ھېكايىسىدۇر.","«jungshen börisi heqqide hékaye» qedimki zaman weqelik hékayisidur."]],"之至":[["事情发展到了之至。","ئىشلار ئەڭ ئاخىرقى نۇقتىغىغا يەتتى.","ishlar eng axirqi nuqtighigha yetti."]],"九头鸟":[["九头鸟是一种神话中的鸟。","جۇتۇنياۋ ئەپسانىلەردىكى بىر قۇش.","jutunyaw epsanilerdiki bir qush."]],"乳牛":[["乳牛每天产奶量很高。","سۈت كالىسىنىڭ كۈندىلىك سۈت مىقدارى بەك يۇقىرى.","süt kalisining kündilik süt miqdari bek yuqiri."]],"乳白色":[["乳白色墙壁让房间显得更明亮。","سۈت رەڭلىك تام ئۆينى تېخىمۇ يورۇق كۆرسىتىدۇ.","süt renglik tam öyni téximu yoruq körsitidu."]],"乾隆":[["乾隆皇帝曾多次下江南巡游。","جۇڭلوڭ ئىمپېراتورى جياڭنەنغا بىر قانچە قېتىم سەپەر قىلغان.","junglong impératori jyangnengha bir qanche qétim seper qilghan."]],"事实根据":[["他的结论有充分的事实根据。","ئۇنىڭ خۇلاسىسىنىڭ تولۇق پاكىت ئاساسى بار.","uning xulasisining toluq pakit asasi bar."]],"二手货":[["这些二手货都是从旧货市场买的。","بۇ ئىككىنچى قول ماللارنىڭ ھەممىسى كونا مال بازىرىدىن سېتىۋېلىنغان.","bu ikkinchi qol mallarning hemmisi kona mal baziridin sétiwélinghan."]],"二分裂":[["细胞通过二分裂进行繁殖。","ھۈجەيرىلەر ئىككىگە بۆلۈنۈش ئارقىلىق كۆپىيىدۇ.","hüjeyriler ikkige bölünüsh arqiliq köpiyidu."]],"互助县":[["互助县历史悠久。","ئۆزئارا ياردەم ناھىيىسىنىڭ تارىخى ئۇزۇن.","öz'ara yardem nahiyisining tarixi uzun."]],"亚洲绶带":[["这种亚洲绶带色彩鲜艳，非常吸引鸟类。","بۇ خىل ئاسىيا لېنتىسى رەڭگى پارقىراق، قۇشلارنى بەك جەلپ قىلىدۇ.","bu xil asiya léntisi renggi parqiraq, qushlarni bek jelp qilidu."]],"交变流电":[["交变流电常用于工业设备。","ئالمىشىپ ئېقىدىغان توك سانائەت ئۈسكۈنىلىرىدە كۆپ ئىشلىتىلىدۇ.","almiship éqidighan tok sanaet üsküniliride köp ishlitilidu."]],"人民战争":[["人民战争是胜利的保障。","خەلق ئۇرۇشى غەلىبىنىڭ كاپالىتى.","xelq urushi ghelibining kapaliti."]],"什叶派":[["什叶派是伊斯兰教的主要分支之一。","شىئە مەزھىپى ئىسلام دىنىنىڭ ئاساسلىق تارماقلىرىنىڭ بىرى.","shie mezhipi islam dinining asasliq tarmaqlirining biri."]],"人参":[["人参是一种珍贵的中药材。","ئادەمگىياھ قىممەتلىك جۇڭيى دورىسى ماتېرىيالى.","ademgiyah qimmetlik jungyi dorisi matériyali."]],"今日头条":[["今日头条是一款热门的新闻应用。","بۈگۈنكى باش خەۋەر بىر ئالقىشلىق خەۋەر ئەپلىكاسىيىسىدۇر.","bügünki bash xewer bir alqishliq xewer eplikasiyisidur."]],"仁民爱物":[["仁民爱物是儒家的重要理念。","خەلقنى سۆيۈش ۋە نەرسىلەرگە مېھرىبان بولۇش كۇڭفۇزىيەنىڭ مۇھىم ئىدىيىسىدۇر.","xelqni söyüsh we nersilerge méhriban bolush kungfuziyening muhim idiyisidur."]],"仔畜":[["仔畜指刚出生不久的幼畜。","زىمىن مال چارۋىسى تۇغۇلغاندىن كۆپ ئۇزۇن ئۆتمىگەن ياش چارۋىنى كۆرسىتىدۇ.","zimin mal charwisi tughulghandin köp uzun ötmigen yash charwini körsitidu."]],"仔姜":[["这道菜用了新鲜的仔姜提味。","بۇ تائام يېڭى زىمىن زەنجىبىلى بىلەن تەم قوشقان.","bu taam yéngi zimin zenjibili bilen tem qoshqan."]],"仗势":[["他仗势欺人，令人不齿。","ئۇ كۈچ-ھوقۇقىغا تايىنىپ باشقىلارنى بوزەك قىلىدۇ، بۇ كىشىلەرنى يىرگىندۈرىدۇ.","u küch-hoquqigha tayinip bashqilarni bozek qilidu, bu kishilerni yirgindüridu."]],"仗势欺人":[["他仗势欺人，让人无法忍受。","ئۇ كۈچ-ھوقۇقىغا تايىنىپ باشقىلارنى بوزەك قىلىدۇ، بۇنى كۆتۈرۈش تەس.","u küch-hoquqigha tayinip bashqilarni bozek qilidu, buni kötürüsh tes."]],"伊利埃斯库":[["伊利埃斯库是著名的画家。","ئىلىئېسكۇ داڭلىق رەسسام.","iliésku dangliq ressam."]],"布告栏":[["布告栏上贴满了通知。","ئېلان تاختىسىغا ئۇقتۇرۇشلار تولا چاپلانغان.","élan taxtisigha uqturushlar tola chaplanghan."]],"作古":[["这些习俗已经作古了。","بۇ ئادەتلەر ئاللىبۇرۇن ئۆتكەن.","bu adetler alliburun ötken."]],"佛心":[["保持佛心，才能内心平静、待人宽容。","بۇددا قەلبىنى ساقلاپ، ئاندىن ئىچكى دۇنياسى تىنچ بولۇپ، باشقىلارغا كەڭ قورساقلىق بىلەن مۇئامىلە قىلالايدۇ.","budda qelbini saqlap, andin ichki dunyasi tinch bolup, bashqilargha keng qorsaqliq bilen muamile qilalaydu."]],"佩剑":[["他腰间佩剑，威风凛凛。","ئۇ بېلىغا قىلىچ ئېسىپ، ھەيۋەتلىك كۆرۈنىدۇ.","u béligha qilich ésip, heywetlik körünidu."]],"佳木斯市":[["佳木斯市位于黑龙江省东部。","جيامۇسى شەھىرى خېيلۇڭجياڭ ئۆلكىسىنىڭ شەرقىي قىسمىدا جايلاشقان.","jyamusi shehiri xéylungjyang ölkisining sherqiy qismida jaylashqan."]],"伸开":[["他将双臂伸开，仿佛拥抱整个世界。","ئۇ ئىككى قولىنى سوزۇپ، پۈتۈن دۇنيانى قۇچاقلىغاندەك بولدى.","u ikki qolini sozup, pütün dunyani quchaqlighandek boldi."]],"俄底浦斯情结":[["俄底浦斯情结是心理学中的术语。","ئودىپۇس كومپلېكسى پسىخولوگىيەدىكى بىر ئاتالغۇ.","odipus kompléksi psixologiyediki bir atalghu."]],"俄乌":[["俄乌冲突持续了多年。","ئورۇس-ئۇكرائىنا توقۇنۇشى كۆپ يىللاردىن بېرى داۋاملاشتى.","orus-ukraina toqunushi köp yillardin béri dawamlashti."]],"俄而":[["俄而天晴，阳光普照大地。","ئازغىنە ۋاقىتتىن كېيىن ھاۋا ئېچىلىپ، قۇياش نۇرى يەر يۈزىنى يورۇتتى.","azghine waqittin kéyin hawa échilip, quyash nuri yer yüzini yorutti."]],"信神者":[["信神者对宗教充满虔诚。","خۇداغا ئىشەنگۈچىلەر دىنغا تولۇق ئېتىقاد قىلىدۇ.","xudagha ishengüchiler dingha toluq étiqad qilidu."]],"信奉":[["他信奉佛教，遵守戒律。","ئۇ بۇددا دىنىغا ئېتىقاد قىلىدۇ، پەرزلەرگە رىئايە قىلىدۇ.","u budda dinigha étiqad qilidu, perzlerge riaye qilidu."]],"信义":[["他们以信义赢得了客户的信任。","ئۇلار سەمىمىيەت ۋە ئىشەنچ بىلەن خېرىدارلارنىڭ ئىشەنچىسىگە ئېرىشتى.","ular semimiyet we ishench bilen xéridarlarning ishenchisige érishti."]],"偷生":[["他偷生苟活，毫无尊严。","ئۇ نومۇسسىز ھالدا ياشاپ، ھېچقانداق ئىززەت-ھۆرمىتى يوق.","u nomussiz halda yashap, héchqandaq izzet-hörmiti yoq."]],"傲人":[["她的成绩令人傲人。","ئۇنىڭ نەتىجىسى كىشىنى پەخىرلەندۈرىدۇ.","uning netijisi kishini pexirlendüridu."]],"传旨":[["皇帝通过诏书传旨全国。","ئىمپېراتور پەرمان ئارقىلىق پۈتۈن مەملىكەتكە بۇيرۇق چۈشۈردى.","impérator perman arqiliq pütün memliketke buyruq chüshürdi."]],"催更":[["读者催更最新章节。","ئوقۇرمەنلەر ئەڭ يېڭى بابنى تېزرەك يېڭىلاشنى ئالدىراتماقتا.","oqurmenler eng yéngi babni tézrek yéngilashni aldiratmaqta."]],"借过":[["他借过几次书，都很顺利。","ئۇ bir neçə قېتىم كىتاب قەرز ئالدى، ھەممىسى ئوڭۇشلۇق بولدى.","u bir neçə qétim kitab qerz aldi, hemmisi ongushluq boldi."]],"倾覆":[["船只突然发生倾覆。","كېمە تۇيۇقسىز ئۆرۈلۈپ كەتتى.","kéme tuyuqsiz örülüp ketti."]],"像样":[["这件衣服看起来挺像样的。","بۇ كىيىم كۆرۈنۈشتە خېلى مۇۋاپىق.","bu kiyim körünüshte xéli muwapiq."]],"传票":[["法院寄来了传票。","سوت مەھكىمىسى چاقىرىق خېتىنى ئەۋەتتى.","sot mehkimisi chaqiriq xétini ewetti."]],"倾盆":[["暴雨倾盆而下，令人措手不及。","قويۇن يامغۇر قۇيۇپ، كىشىنى تەييارلىقسىز قالدۇردى.","qoyun yamghur quyup, kishini teyyarliqsiz qaldurdi."]],"元末":[["元末时期社会动荡不安。","يۈەن سۇلالىسىنىڭ ئاخىرقى مەزگىلىدە جەمئىيەت قالايمىقان ئىدى.","yüen sulalisining axirqi mezgilide jem'iyet qalaymiqan idi."]],"光柱":[["光柱从地面直冲云霄，气势磅礴。","نۇر تۈۋرۈكى يەردىن ئاسمانغا قاراپ ئۇرۇلدى، ھەيۋەتلىك مەنزىرىسى بار.","nur tüwrüki yerdin asmangha qarap uruldi, heywetlik menzirisi bar."]],"光影":[["光影效果增强画面表现力。","يورۇقلۇق-سايە ئۈنۈمى رەسىمنىڭ ئىپادىلەش كۈچىنى كۈچەيتىدۇ.","yoruqluq-saye ünümi resimning ipadilesh küchini kücheytidu."]],"光谱":[["彩虹属于可见光谱的一部分。","ھەسارە پەلەمپىيى كۆرۈنەرلىك نۇر تەۋەلىكىنىڭ بىر قىسمى.","hesare pelempiyi körünerlik nur tewelikining bir qismi."]],"克氏黑鳍鳈":[["克氏黑鳍鳈是一种小型淡水鱼。","كرىۋېتسا قارا قاناتلىق چىباق بىر خىل كىچىك تاتلىق سۇ بېلىقىدۇر.","kriwétsa qara qanatliq chibaq bir xil kichik tatliq su béliqidur."]],"全数":[["所有款项都已全数到账。","بارلىق پۇللار تولۇق ھېساباتقا كىرگۈزۈلدى.","barliq pullar toluq hésabatqa kirgüzüldi."]],"兖州":[["兖州是山东的历史名城。","يەنژۇ بۆلۈكى شەندۇڭنىڭ تارىخىي داڭلىق شەھىرى.","yenzhu bölüki shendungning tarixiy dangliq shehiri."]],"入籍":[["她申请入籍成为公民。","ئۇ پۇقرا بولۇش ئۈچۈن ئىلتىماس قىلدى.","u puqra bolush üchün iltimas qildi."]],"全称":[["这个缩写的全称是“国际组织”。","بۇ قىسقارتىلما سۆزنىڭ تولۇق نامى «خەلقئارا تەشكىلات».","bu qisqartilma sözning toluq nami «xelq'ara teshkilat»."]],"内中":[["内中另有玄机。","ئىچىدە يەنە باشقا سىر بار.","ichide yene bashqa sir bar."]],"八廓":[["八廓是拉萨古城的核心区域。","باركور لھاسا قەدىمىي شەھىرىنىڭ يادرولۇق رايونى.","barkor lhasa qedimiy shehirining yadroluq rayoni."]],"八荣八耻":[["八荣八耻是社会主义核心价值观的一部分。","سەككىز شەرەپ سەككىز ئۇيات سوتسىيالىستىك ئاساسىي قىممەت قارىشىنىڭ بىر قىسمى.","sekkiz sherep sekkiz uyat sotsiyalistik asasiy qimmet qarishining bir qismi."]],"共价键":[["共价键是原子间的结合方式。","ئورتاق ۋالېنتلىق باغ ئاتوملار ئارىسىدىكى بىرلىشىش ئۇسۇلىدۇر.","ortaq waléntliq bagh atomlar arisidiki birlishish usulidur."]],"兼蓄":[["他广泛兼蓄各类知识。","ئۇ ھەر خىل بىلىملەرنى كەڭ دائىرىدە توپلىغان.","u her xil bilimlerni keng dairide toplighan."]],"公共零点":[["公共零点用于计时。","ئاممىۋى نۆل نۇقتا ۋاقىت ھېسابلاشتا ئىشلىتىلىدۇ.","ammiwi nöl nuqta waqit hésablashta ishlitilidu."]],"冒犯者":[["冒犯者受到了惩罚。","ھاقارەت قىلغۇچى جازالاندى.","haqaret qilghuchi jazalandi."]],"冤诬":[["他遭人冤诬陷害。","ئۇ باشقىلار تەرىپىدىن ئەپسۇسلىك بىلەن تۆھمەت قىلىندى ۋە زىيانغا ئۇچرىدى.","u bashqilar teripidin epsuslik bilen töhmet qilindi we ziyangha uchridi."]],"凌波舞":[["她的舞姿如凌波舞般优雅。","ئۇنىڭ ئۇسسۇلى لىڭبو ئۇسسۇلىدەك نەپىس.","uning ussuli lingbo ussulidek nepis."]],"分久必合，合久必分":[["分久必合，合久必分。","ئايرىلغان ئۇزۇن بولسا چوقۇم قوشۇلىدۇ، قوشۇلغان ئۇزۇن بولسا چوقۇم ئايرىلىدۇ.","ayrilghan uzun bolsa choqum qoshulidu, qoshulghan uzun bolsa choqum ayrilidu."]],"剖肝沥胆":[["他剖肝沥胆地讲述经历。","ئۇ باغرىقانى ئېچىپ ئۆز باشتىن كەچۈرگەنلىرىنى سۆزلەپ بەردى.","u baghriqani échip öz bashtin kechürgenlirini sözlep berdi."]],"剧透":[["别剧透结局。","ئاخىرقى نەتىجىنى ئېيتىپ قويماڭ.","axirqi netijini éytip qoymang."]],"切合实际":[["设计必须切合实际，满足用户需求。","Dizayn chөqum rېalliqqa uyghun bolushi, ishlәtküchilәrning ehtiyajini qanaәtlәndürüshi kېrәk.","Dizayn chөqum réalliqqa uyghun bolushi, ishlәtküchilәrning ehtiyajini qanaәtlәndürüshi kérәk."]],"创练":[["每天坚持创练才能进步。","ھەر كۈنى چېنىقىشنى داۋاملاشتۇرغاندىلا ئىلگىرىلەشكە بولىدۇ.","her küni chéniqishni dawamlashturghandila ilgirileshke bolidu."]],"刨冰":[["夏天吃刨冰，清凉又美味。","يازدا مۇز قىرىقىچە يېسە، سالقىن ھەم لەززەتلىك.","yazda muz qiriqiche yése, salqin hem lezzetlik."]],"加德西":[["加德西是当地的一个社区。","گادېسى يەرلىك بىر جەمئىيەت.","gadési yerlik bir jem'iyet."]],"加拿大太平洋铁路":[["加拿大太平洋铁路连接东西海岸。","كانادا تىنچ ئوكيان تۆمۈريولى شەرق ۋە غەرب قىرغاقلىرىنى تۇتاشتۇرىدۇ.","kanada tinch okyan tömüryoli sherq we gherb qirghaqlirini tutashturidu."]],"加注":[["需要向容器中加注液体。","قاچىغا سۇيۇقلۇق قۇيۇش كېرەك.","qachigha suyuqluq quyush kérek."]],"功能集":[["功能集整合了多种实用工具。","ئىقتىدار توپلىمى ھەر خىل ئەمەلىي قوراللارنى بىرلەشتۈردى.","iqtidar toplimi her xil emeliy qorallarni birleshtürdi."]],"功过":[["功过需客观评价。","تۆھپە ۋە خاتالىقنى ئوبيېكتىپ باھالاش كېرەك.","töhpe we xataliqni obyéktip bahalash kérek."]],"包吃包住":[["公司提供包吃包住。","شىركەت تاماق ۋە تۇرالغۇ بىلەن تەمىنلەيدۇ.","shirket tamaq we turalghu bilen teminleydu."]],"包饭":[["学校提供免费的包饭服务。","مەكتەپ ھەقسىز تاماق مۇلازىمىتى تەمىنلەيدۇ.","mektep heqsiz tamaq mulazimiti teminleydu."]],"化学战":[["化学战在战争中受到严格禁止。","خىمىيىلىك ئۇرۇش ئۇرۇشتا قاتتىق چەكلىنىدۇ.","ximiyilik urush urushta qattiq cheklinidu."]],"北竿":[["北竿是台湾的一个小乡镇。","بېيگان تەيۋەندىكى بىر كىچىك يېزا.","béygan teywendiki bir kichik yéza."]],"升息":[["央行决定升息。","مەركىزىي بانكا ئۆسۈم نىسبىتىنى كۆتۈرۈشكە قارار قىلدى.","merkiziy banka ösüm nisbitini kötürüshke qarar qildi."]],"千夫":[["千夫所指，无疾而终。","مىڭ ئادەم بارماق تىكىسە، كېسەلسىز ئۆلۈپ كېتىدۇ.","ming adem barmaq tikise, késelsiz ölüp kétidu."]],"卒业":[["他顺利卒业，获得学位。","ئۇ ئوڭۇشلۇق ئوقۇش پۈتتۈرۈپ، ئىلمىي دەرىجە ئالدى.","u ongushluq oqush püttürüp, ilmiy derije aldi."]],"南城县":[["南城县隶属于江西省抚州市。","نەنچېڭ ناھىيەسى جياڭشى ئۆلكىسىنىڭ فۇجۇ شەھىرىگە قارايدۇ.","nenchéng nahiyesi jyangshi ölkisining fuju shehirige qaraydu."]],"千赫":[["这个收音机支持到千赫频率。","بۇ رادىئو مىڭ گېرتس چاستوتىسىغىچە قوللايدۇ.","bu radio ming gérts chastotisighiche qollaydu."]],"博客":[["他经常在自己的博客上分享心得。","ئۇ دائىم ئۆزىنىڭ بىلوگىدا تەسىراتلىرىنى ئورتاقلىشىدۇ.","u daim özining bilogida tesiratlirini ortaqlishidu."]],"博爱县":[["博爱县位于河南省。","بوۋئەي ناھىيىسى خېنەن ئۆلكىسىدە جايلاشقان.","bow'ey nahiyisi xénen ölkiside jaylashqan."]],"南竿":[["南竿乡风景优美。","جەنۇبىي گەن يېزىسىنىڭ مەنزىرىسى گۈزەل.","jenubiy gen yézisining menzirisi güzel."]],"南华县":[["南华县历史悠久，资源丰富。","جەنۇبىي خۇا ناھىيىسى ئۇزۇن تارىخقا ئىگە، بايلىقلىرى مول.","jenubiy xua nahiyisi uzun tarixqa ige, bayliqliri mol."]],"原生质":[["原生质是细胞的基本物质。","ئەسلىي ماددا ھۈجەيرىنىڭ ئاساسىي ماددىسىدۇر.","esliy madda hüjeyrining asasiy maddisidur."]],"原产地":[["原产地决定了产品的品质。","ئەسلىي ئىشلەپچىقىرىلغان جاي مەھسۇلاتنىڭ سۈپىتىنى بەلگىلەيدۇ.","esliy ishlepchiqirilghan jay mehsulatning süpitini belgileydu."]],"反问语气":[["他的反问语气让人难以反驳。","ئۇنىڭ ئەكسىيە سوئال ئاھاڭى كىشىنىڭ رەددىيە بېرىشىنى قىيىنلاشتۇردى.","uning eksiye soal ahangi kishining reddiye bérishini qiyinlashturdi."]],"反人道罪行":[["反人道罪行不可宽恕。","ئىنسانىيەتكە قارشى جىنايەتلەر كەچۈرۈلمەيدۇ.","insaniyetke qarshi jinayetler kechürülmeydu."]],"厌气":[["房间里弥漫着一种令人窒息的厌气，让人难以忍受。","ئۆيدە بوغۇچى زېرىكىش پۇرىقى تارقىلىپ، بۇنىڭغا چىدىغىلى بولمايدۇ.","öyde boghuchi zérikish puriqi tarqilip, buninggha chidighili bolmaydu."]],"卡拉":[["卡拉是一种古老的乐器。","كارا بىر قەدىمىي چالغۇ.","kara bir qedimiy chalghu."]],"口锋":[["他的口锋犀利，言辞有力。","ئۇنىڭ ئېغىزى ئۆتكۈر، سۆزى كۈچلۈك.","uning éghizi ötkür, sözi küchlük."]],"取回":[["他取回了之前寄出的包裹。","ئۇ ئىلگىرى ئەۋەتكەن بوغچىسىنى ئېلىپ كەلدى.","u ilgiri ewetken boghchisini élip keldi."]],"可汗":[["古代可汗拥有至高权力。","قەدىمكى خاقانلار ئەڭ يۇقىرى ھوقۇققا ئىگە ئىدى.","qedimki xaqanlar eng yuqiri hoquqqa ige idi."]],"古生代":[["古生代是地质历史上的一个重要时期。","پالېئوزوي ئېراسى گېئولوگىيە تارىخىدىكى مۇھىم بىر دەۋردۇر.","paléozoy érasi géologiye tarixidiki muhim bir dewrdur."]],"可遇不可求":[["这样的机会可遇不可求。","بۇنداق پۇرسەت تەلەپ قىلساڭمۇ تاپالمايسەن.","bundaq purset telep qilsangmu tapalmaysen."]],"台克球":[["台克球是一种运动。","تېقچە توپ بىر خىل تەنتەربىيە.","téqche top bir xil tenterbiye."]],"古体诗":[["这首古体诗用词简练，意境深远。","بۇ قەدىمىي ئۇسلۇبتىكى شېئىر ئىشلىتىلگەن سۆزلەردە ئىخچام، مەنىسى چوڭقۇر.","bu qedimiy uslubtiki shéir ishlitilgen sözlerde ixcham, menisi chongqur."]],"吃枪药":[["他今天吃枪药了，脾气特别大。","ئۇ بۈگۈن ئوت يېگەندەك، مىجەزى بەك تەرس بولدى.","u bügün ot yégendek, mijezi bek ters boldi."]],"史高比耶":[["史高比耶是这部小说的主要人物。","سكوپيە بۇ روماننىڭ ئاساسلىق پېرسوناژى.","skopye bu romanning asasliq pérsonazhi."]],"吉迪恩":[["吉迪恩是一位著名的天文学家和数学家。","گىدىئون داڭلىق ئاسترونوم ۋە ماتېماتىك.","gidion dangliq astronom we matématik."]],"叨扰":[["很抱歉叨扰您，但有事相求。","سىزنى ئاۋارە قىلغانلىقىم ئۈچۈن كەچۈرۈڭ، ئەمما بىر ئىش سورايدىغان بولۇپ قالدىم.","sizni aware qilghanliqim üchün kechürüng, emma bir ish soraydighan bolup qaldim."]],"同型性":[["这种物质具有同型性。","بۇ خىل ماددا ئوخشاش تىپلىق خۇسۇسىيەتكە ئىگە.","bu xil madda oxshash tipliq xususiyetke ige."]],"同性相斥":[["同性相斥是基本物理现象。","ئوخشاش قۇتۇپلار بىر-بىرىنى ئىتتىرىدۇ، بۇ ئاساسىي فىزىكىلىق ھادىسە.","oxshash qutuplar bir-birini ittiridu, bu asasiy fizikiliq hadise."]],"吹管":[["他正在吹管乐器。","ئۇ ھازىر پۈۋلەپ چالىدىغان چالغۇنى چېلىۋاتىدۇ.","u hazir püwlep chalidighan chalghuni chéliwatidu."]],"吹管乐":[["吹管乐需要良好的气息控制。","پۈۋلەپ چالىدىغان چالغۇنى چېلىش ياخشى نەپەس كونتروللۇقىنى تەلەپ قىلىدۇ.","püwlep chalidighan chalghuni chélish yaxshi nepes kontrolluqini telep qilidu."]],"名落孙山":[["他考试名落孙山，十分沮丧。","ئۇ ئىمتىھاندىن ئۆتەلمەي، بەك رۇھىي چۈشكۈنلۈككە چۆمدى.","u imtihandin ötelmey, bek ruhiy chüshkünlükke chömdi."]],"名贵":[["这瓶香水价格名贵。","بۇ خۇشپۇراق سۇيۇقلۇقنىڭ باھاسى قىممەت.","bu xushpuraq suyuqluqning bahasi qimmet."]],"哈罗德":[["哈罗德是英国前首相。","ھارولد بىرتانىيەنىڭ سابىق باش مىنىستىرى.","harold birtaniyening sabiq bash ministiri."]],"哥伦比亚特区":[["哥伦比亚特区位于华盛顿。","كولۇمبىيە ئالاھىدە رايونى ۋاشىنگتوندىن جايلاشقان.","kolumbiye alahide rayoni washingtondin jaylashqan."]],"呵喝":[["他呵喝一声，让众人安静。","ئۇ بىر ئاۋاز چىقىرىپ، كۆپچىلىكنى جىم قىلدى.","u bir awaz chiqirip, köpchilikni jim qildi."]],"呢喃细语":[["他们俩在角落里呢喃细语。","ئۇلار ئىككىيلەن بۇلۇڭدا پىچىرلىشىپ سۆزلىشىۋاتاتتى.","ular ikkiylen bulungda pichirliship sözlishiwatatti."]],"品秩":[["古代官职有严格的品秩划分。","قەدىمكى دەۋرلەردىكى ۋەزىپىلەرنىڭ دەرىجە تەقسىماتى قاتتىق ئىدى.","qedimki dewrlerdiki wezipilerning derije teqsimati qattiq idi."]],"哄堂大笑":[["他的幽默让全场哄堂大笑。","ئۇنىڭ يۇمۇرى كۈلكىلىك پۈتۈن مەيداننى كۈلدۈرۈپ كەتتى.","uning yumuri külkilik pütün meydanni küldürüp ketti."]],"唐睿宗":[["唐睿宗在位时间较短。","تاڭ رۈيزۇڭنىڭ ھۆكۈمرانلىق مۇددىتى بىر قەدەر قىسقا بولغان.","tang rüyzungning hökümranliq mudditi bir qeder qisqa bolghan."]],"唐懿宗":[["唐懿宗时期宦官势力日益膨胀。","تاڭ يىزۇڭ دەۋرىدە خانلىق ئەمەلدارلىرىنىڭ كۈچى كۈنسېرى كېڭەيگەن.","tang yizung dewride xanliq emeldarlirining küchi künséri kéngeygen."]],"商城":[["商城里有各种各样的商品可供选择。","سودا سارىيىدا تاللاشقا بولىدىغان ھەر خىل مال تاۋارلار بار.","soda sariyida tallashqa bolidighan her xil mal tawarlar bar."]],"唇枪舌剑":[["辩论时，双方唇枪舌剑，激烈交锋。","مۇنازىرە قىلغاندا، ئىككى تەرەپ لەۋ-تىل قورالىدا كەسكىن ئېلىشىدۇ.","munazire qilghanda, ikki terep lew-til qoralida keskin élishidu."]],"善行":[["他的善行赢得了大家的尊重。","ئۇنىڭ ياخشى ئىشلىرى كۆپچىلىكنىڭ ھۆرمىتىگە ئېرىشتى.","uning yaxshi ishliri köpchilikning hörmitige érishti."]],"喜不自禁":[["她喜不自禁，笑个不停。","ئۇ خۇشاللىقىنى باسالماي، توختىماي كۈلۈپ تۇردى.","u xushalliqini basalmay, toxtimay külüp turdi."]],"单枪匹马":[["他单枪匹马完成了任务。","ئۇ يالغۇز ئۆزى بىلەن ۋەزىپىنى تاماملىدى.","u yalghuz özi bilen wezipini tamamlidi."]],"嘉山":[["这座嘉山风景优美，吸引许多游客。","بۇ جىيەشەن تېغىنىڭ مەنزىرىسى گۈزەل بولۇپ، نۇرغۇن ساياھەتچىلەرنى جەلپ قىلىدۇ.","bu jiyeshen téghining menzirisi güzel bolup, nurghun sayahetchilerni jelp qilidu."]],"嘴快心直":[["他嘴快心直，从不拐弯抹角。","ئۇنىڭ ئاغزى تېز، كۆڭلى ئوچۇق، ھەرگىز ئەگرى-توقايلىق قىلمايدۇ.","uning aghzi téz, köngli ochuq, hergiz egri-toqayliq qilmaydu."]],"吨公里":[["运输量以吨公里来计算。","توشۇش مىقدارى توننا كىلومېتىر بىلەن ھېسابلىنىدۇ.","toshush miqdari tonna kilométir bilen hésablinidu."]],"吨数":[["这批货物的吨数超过了预期。","بۇ تۈركۈم مالنىڭ توننا سانى كۈتكەندىن ئېشىپ كەتتى.","bu türküm malning tonna sani kütkendin éship ketti."]],"吓傻":[["她被突如其来的消息吓傻了。","ئۇ تۇيۇقسىز كەلگەن خەۋەردىن ئەس-ھوشىنى يوقىتىپ قالدى.","u tuyuqsiz kelgen xewerdin es-hoshini yoqitip qaldi."]],"严刑拷打":[["敌人对他进行了严刑拷打。","دۈشمەنلەر ئۇنى قاتتىق ئازابلادى.","düshmenler uni qattiq azabladi."]],"严复":[["严复是中国近代著名的翻译家。","يەن فۇ جۇڭگونىڭ يېقىنقى زامان مەشھۇر تەرجىمانى.","yen fu junggoning yéqinqi zaman meshhur terjimani."]],"严词":[["他用严词批评了同事的疏忽。","ئۇ خىزمەتدىشىنىڭ بىپەرۋالىقىنى قاتتىق سۆزلەر بىلەن تەنقىد قىلدى.","u xizmetdishining biperwaliqini qattiq sözler bilen tenqid qildi."]],"四境":[["四境之地是古代边界的代称。","تۆت چېگرا زېمىنى قەدىمكى چېگرا ئاتىلىشىدۇر.","töt chégra zémini qedimki chégra atilishidur."]],"四方台区":[["四方台区位于城市的西北方向。","سىفاڭتەي رايونى شەھەرنىڭ شىمالىي غەربىي تەرىپىدە جايلاشقان.","sifangtey rayoni sheherning shimaliy gherbiy teripide jaylashqan."]],"四海升平":[["四海升平意味着世界和平稳定。","تۆت دېڭىز تىنچلىقى دۇنيا تىنچلىقى ۋە مۇقىملىقىنى بىلدۈرىدۇ.","töt déngiz tinchliqi dunya tinchliqi we muqimliqini bildüridu."]],"圆柱体":[["圆柱体有两个平行的圆形底面。","يۇمىلاق تۈۋرۈك جىسىمنىڭ ئىككى پاراللېل يۇمىلاق ئاستى يۈزى بار.","yumilaq tüwrük jisimning ikki parallél yumilaq asti yüzi bar."]],"圆谎":[["他圆谎的漏洞被轻易揭穿。","ئۇنىڭ يالغاننى يېپىشتىكى كەمتۈكلۈكى ئاسانلا ئاشكارىلاندى.","uning yalghanni yépishtiki kemtüklüki asanla ashkarilandi."]],"国际文传通讯社":[["国际文传通讯社向全球发布重要的新闻信息。","خەلقئارا ئاخبارات ئاگېنتلىقى دۇنياغا مۇھىم خەۋەر ئۇچۇرلىرىنى تارقىتىدۇ.","xelq'ara axbarat agéntliqi dunyagha muhim xewer uchurlirini tarqitidu."]],"图集":[["这本图集记录了世界各地的风景。","بۇ رەسىملەر توپلىمى دۇنيانىڭ ھەر قايسى جايلىرىدىكى مەنزىرىلەرنى خاتىرىلەيدۇ.","bu resimler toplimi dunyaning her qaysi jayliridiki menzirilerni xatirileydu."]],"地质学家":[["地质学家通过钻探获取地下岩层样本。","گېئولوگلار بۇرغىلاش ئارقىلىق يەر ئاستى قاتلاملىرىنىڭ ئۈلگىلىرىنى ئالىدۇ.","géologlar burghilash arqiliq yer asti qatlamlirining ülgilirini alidu."]],"城外":[["城外是一片宁静的田野。","شەھەر سىرتى ئىپارلىق ئېتىزلىقتۇر.","sheher sirti iparliq étizliqtur."]],"地角天涯":[["地角天涯形容极远的地方。","يەر چېتى ۋە ئاسمان چېتى ئىنتايىن يىراق جاينى تەسۋىرلەيدۇ.","yer chéti we asman chéti intayin yiraq jayni teswirleydu."]],"塔城市":[["塔城市是塔城地区的行政中心。","چۆچەك شەھىرى چۆچەك رايونىنىڭ مەمۇرىي مەركىزىدۇر.","chöchek shehiri chöchek rayonining memuriy merkizidur."]],"塞万提斯":[["塞万提斯是《堂吉诃德》的作者。","سېرۋانتېس «دون كىخوت» نىڭ ئاپتورى.","sérwantés «don kixot» ning aptori."]],"塞车":[["今天路上严重塞车。","بۈگۈن يولدا ئېغىر تىقىلىشچىلىق بولدى.","bügün yolda éghir tiqilishchiliq boldi."]],"填充剂":[["这种填充剂效果很好。","بۇ خىل تولدۇرغۇچىنىڭ ئۈنۈمى ياخشى.","bu xil toldurghuchining ünümi yaxshi."]],"墓主":[["墓主的名字刻在墓碑上。","قەبرە ئىگىسىنىڭ ئىسمى قەبرە تېشىغا ئويۇلغان.","qebre igisining ismi qebre téshigha oyulghan."]],"塞尔达":[["塞尔达是《塞尔达传说》系列的主角。","زېلدا «زېلدا ئەپسانىسى» توركۇمىنىڭ باش پېرسوناژى.","zélda «zélda epsanisi» torkumining bash pérsonazhi."]],"塞缪尔":[["塞缪尔是一位著名的作家。","سامۇئېل داڭلىق بىر يازغۇچى.","samuél dangliq bir yazghuchi."]],"墨西拿":[["墨西拿是意大利的一个港口城市。","مېسسىنا ئىتالىيەنىڭ بىر پورت شەھىرى.","méssina italiyening bir port shehiri."]],"壁助":[["壁助项目帮助了很多人。","دىوار ياردەم تۈرى نۇرغۇن كىشىلەرگە ياردەم قىلدى.","dioar yardem türi nurghun kishilerge yardem qildi."]],"坚牢":[["这座桥非常坚牢，能承受重压。","بۇ كۆۋرۈك ئىنتايىن مۇستەھكەم، ئېغىر بېسىمغا بەرداشلىق بېرەلەيدۇ.","bu köwrük intayin mustehkem, éghir bésimgha berdashliq béreleydu."]],"多如牛毛":[["他的错误多如牛毛。","ئۇنىڭ خاتالىقى تۈكەلسىز كۆپ.","uning xataliqi tükelsiz köp."]],"多此一举":[["这样做完全是多此一举。","بۇنداق قىلىش پۈتۈنلەي ئارتۇقچە ئىش.","bundaq qilish pütünley artuqche ish."]],"多灾多难":[["这个地区多灾多难。","بۇ رايون ئاپەت-بالالار كۆپ يۈز بېرىدىغان جايدۇر.","bu rayon apet-balalar köp yüz béridighan jaydur."]],"大夏":[["大夏曾是上海著名的建筑。","داشيا شاڭخەينىڭ مەشھۇر بىناسى ئىدى.","dashya shangxeyning meshhur binasi idi."]],"大小姐":[["大小姐性格很温柔。","چوڭ خانىم خاراكتېرى ئىنتايىن يۇمشاق.","chong xanim xaraktéri intayin yumshaq."]],"大智若愚":[["他看似愚钝，实则大智若愚。","ئۇ ئەخمەقكە ئوخشىسىمۇ، ئەمەلىيەتتە چوڭ ئەقىللىق.","u exmeqke oxshisimu, emeliyette chong eqilliq."]],"大陆性":[["大陆性气候干燥。","قۇرۇقلۇق خاراكتېرلىك ئىقلىم قۇرغاق بولىدۇ.","quruqluq xaraktérlik iqlim qurghaq bolidu."]],"天主的羔羊":[["耶稣被称为天主的羔羊，象征纯洁与牺牲。","ئىسا خۇدانىڭ قوزىسى دەپ ئاتىلىدۇ، پاكلىق ۋە قۇربانلىقنى سىمۋول قىلىدۇ.","isa xudaning qozisi dep atilidu, pakliq we qurbanliqni simwol qilidu."]],"天文馆":[["天文馆向公众展示天文知识。","ئاسترونومىيە سارىيى جامائەتكە ئاسترونومىيە بىلىملىرىنى كۆرسىتىدۇ.","astronomiye sariyi jamaetke astronomiye bilimlirini körsitidu."]],"大福":[["他吃了一个大福，觉得非常美味。","ئۇ بىر چوڭ بەختلىك تائام يېدى ۋە ئىنتايىن تەملىك دەپ ھېس قىلدى.","u bir chong bextlik taam yédi we intayin temlik dep hés qildi."]],"大箐山":[["大箐山是著名的旅游景点。","چوڭچىڭ تېغى مەشھۇر ساياھەت نۇقتىسى.","chongching téghi meshhur sayahet nuqtisi."]],"天坑":[["天坑是一种独特的地质景观。","تەڭرى ئورىسى بىر ئۆزگىچە گېئولوگىيەلىك مەنزىرىدۇر.","tengri orisi bir özgiche géologiyelik menziridur."]],"天黑":[["天黑后，街上行人稀少。","ئاسمان قاراڭغۇلاشقاندىن كېيىن، كوچىدىكى پىيادىلەر ئاز.","asman qarangghulashqandin kéyin, kochidiki piyadiler az."]],"天玑":[["天玑是天琴座的重要恒星。","تيەنجى لىرا يۇلتۇز تۈركۈمىنىڭ مۇھىم يۇلتۇزىدۇر.","tyenji lira yultuz türkümining muhim yultuzidur."]],"天网":[["天网恢恢，疏而不失。","تەبىئەت تورى كەڭ ۋە چوڭدۇر، سىرتىدا قالمايدۇ.","tebiet tori keng we chongdur, sirtida qalmaydu."]],"天网恢恢":[["天网恢恢，疏而不漏。","تەبىئەت تورى كەڭ ۋە چوڭدۇر، سىرتىدا قالمايدۇ.","tebiet tori keng we chongdur, sirtida qalmaydu."]],"天翻地覆":[["战争让城市天翻地覆。","ئۇرۇش شەھەرنى ئاستىن-ئۈستى قىلدى.","urush sheherni astin-üsti qildi."]],"夫妻相":[["夫妻相是指两人相像。","ئەر-خوتۇن ئوخشاشلىقى ئىككى كىشىنىڭ ئوخشىشىنى كۆرسىتىدۇ.","er-xotun oxshashliqi ikki kishining oxshishini körsitidu."]],"失怙":[["他失怙后独自抚养孩子长大。","ئۇ ئاتىسىدىن ئايرىلغاندىن كېيىن بالىلىرىنى يالغۇز بېقىپ چوڭ قىلدى.","u atisidin ayrilghandin kéyin balilirini yalghuz béqip chong qildi."]],"大鹏":[["大鹏鸟在神话中象征力量。","چوڭ پەڭ قۇشى ئەپسانىلەردە كۈچنى سىمۋول قىلىدۇ.","chong peng qushi epsanilerde küchni simwol qilidu."]],"奔窜":[["敌人开始奔窜。","دۈشمەن قاچىشقا باشلىدى.","düshmen qachishqa bashlidi."]],"套儿":[["这个套儿设计巧妙。","بۇ يۈرۈمچە لايىھەسى چىرايلىق.","bu yürümche layihesi chirayliq."]],"套房":[["这家酒店提供豪华套房。","بۇ مېھمانخانا ھەشەمەتلىك يۈرۈم ئۆي تەمىنلەيدۇ.","bu méhmanxana heshemetlik yürüm öy teminleydu."]],"奶精":[["咖啡中加入奶精更香浓。","قەھۋەگە سۈت قوشقاندا تېخىمۇ خۇشبۇي بولىدۇ.","qehwege süt qoshqanda téximu xushbuy bolidu."]],"女士优先":[["在电梯里，女士优先。","لىفتتا ئاياللار ئالدىنقى ئورۇندا.","liftta ayallar aldinqi orunda."]],"妙品":[["这件妙品令人赞叹。","بۇ ئاجايىپ نەرسە كىشىنى ھەيران قالدۇرىدۇ.","bu ajayip nerse kishini heyran qalduridu."]],"威利":[["威利是个聪明孩子。","ۋىللى ئەقىللىق بىر بالا.","willi eqilliq bir bala."]],"姨姥姥":[["我从小就和姨姥姥感情很好。","مەن كىچىكىمدىن باشلاپ مومام بىلەن مۇناسىۋىتىم ياخشى.","men kichikimdin bashlap momam bilen munasiwitim yaxshi."]],"奸杀":[["奸杀是强奸后杀害受害者的恶性犯罪。","زىنا قىلىپ ئۆلتۈرۈش زورلىغاندىن كېيىن زىيانكەشنى ئۆلتۈرۈشنىڭ يامان جىنايىتى.","zina qilip öltürüsh zorlighandin kéyin ziyankeshni öltürüshning yaman jinayiti."]],"姑爹":[["姑爹从小教我写字。","تاغام مېنى كىچىكىمدىن باشلاپ خەت يېزىشنى ئۆگەتتى.","tagham méni kichikimdin bashlap xet yézishni ögetti."]],"季节性":[["这种现象具有季节性。","بۇ خىل ھادىسە پەسىللىك ئالاھىدىلىككە ئىگە.","bu xil hadise pesillik alahidilikke ige."]],"季肋":[["季肋疼痛难忍。","قوۋۇرغا ئاستى ئاغرىقى چىدىغۇسىز.","qowurgha asti aghriqi chidighusiz."]],"子母炮弹":[["子母炮弹能同时发射多枚子弹。","ئانا-بالا ئوقى بىرلا ۋاقىتتا كۆپلىگەن ئوقچىلارنى ئېتىپ چىقىرالايدۇ.","ana-bala oqi birla waqitta köpligen oqchilarni étip chiqiralaydu."]],"守成":[["他守成不易，付出了巨大努力。","ئۇ ئىنشا قىلغان ئىشلارنى ساقلاپ قېلىش ئاسان ئەمەس، ئۇ زور تىرىشچانلىق كۆرسەتتى.","u insha qilghan ishlarni saqlap qélish asan emes, u zor tirishchanliq körsetti."]],"孟加拉":[["孟加拉是一个多民族国家。","بېنگال كۆپ مىللەتلىك دۆلەتتۇر.","béngal köp milletlik dölettur."]],"安全性":[["这个产品的安全性经过严格测试。","بۇ مەھسۇلاتنىڭ بىخەتەرلىكى قاتتىق سىناقتىن ئۆتكۈزۈلگەن.","bu mehsulatning bixeterliki qattiq sinaqtin ötküzülgen."]],"安地斯":[["安地斯山脉贯穿南美洲西部。","ئاندىس تاغ تىزمىسى جەنۇبىي ئامېرىكىنىڭ غەربىنى كېسىپ ئۆتىدۇ.","andis tagh tizmisi jenubiy amérikining gherbini késip ötidu."]],"宕昌县":[["宕昌县拥有丰富的自然资源。","داڭچاڭ ناھىيىسى باي تەبىئىي بايلىققا ئىگە.","dangchang nahiyisi bay tebiiy bayliqqa ige."]],"宣介":[["公司举行了新产品的宣介会。","شىركەت يېڭى مەھسۇلاتنىڭ تونۇشتۇرۇش يىغىنىنى ئۆتكۈزدى.","shirket yéngi mehsulatning tonushturush yighinini ötküzdi."]],"宜阳县":[["宜阳县地处豫陕两省交界。","يىياڭ ناھىيىسى يۈ شەن ئىككى ئۆلكىنىڭ چېگرىسىدا جايلاشقان.","yiyang nahiyisi yü shen ikki ölkining chégrisida jaylashqan."]],"客套话":[["这些只是客套话，不必当真。","بۇلار پەقەت رەسمىي سۆزلەر، جىددىي قاتتىق ئالمىسىڭىزمۇ بولىدۇ.","bular peqet resmiy sözler, jiddiy qattiq almisingizmu bolidu."]],"宽宥":[["老师宽宥了学生的无心之过。","ئوقۇتقۇچى ئوقۇغۇچىنىڭ بىخەتەر خاتالىقىنى كەچۈردى.","oqutquchi oqughuchining bixeter xataliqini kechürdi."]],"宝应县":[["宝应县盛产优质的农产品。","باۋيىڭ ناھىيىسى سۈپەتلىك يېزا ئىگىلىك مەھسۇلاتلىرىنى كۆپ ئىشلەپچىقىرىدۇ.","bawying nahiyisi süpetlik yéza igilik mehsulatlirini köp ishlepchiqiridu."]],"宝武钢铁":[["宝武钢铁是中国大型钢铁企业。","باۋۋۇ پولات-تۆمۈر جۇڭگونىڭ چوڭ تىپتىكى پولات-تۆمۈر كارخانىسى.","bawwu polat-tömür junggoning chong tiptiki polat-tömür karxanisi."]],"小偷":[["小偷从包里偷走了手机。","ئوغرى سومكىدىن يانفوننى ئوغرىلىۋەتتى.","oghri somkidin yanfonni oghriliwetti."]],"专任":[["他专任此职。","ئۇ پەقەت مۇشۇ ۋەزىپىنى ئۆتەيدۇ.","u peqet mushu wezipini öteydu."]],"专攻":[["这位教授专攻人工智能领域的自然语言处理。","بۇ پروفېسسور سۈنئىي ئەقىل ساھەسىدىكى تەبىئىي تىل بىر تەرەپ قىلىشقا مەخسۇس ئىختىساسلاشقان.","bu proféssor sün'iy eqil sahesidiki tebiiy til bir terep qilishqa mexsus ixtisaslashqan."]],"小巷":[["这条小巷藏着许多传统小吃店。","بۇ كىچىك كوچىدا نۇرغۇن ئەنئەنىۋى تائامخانىلار يوشۇرۇنغان.","bu kichik kochida nurghun en'eniwi taamxanilar yoshurunghan."]],"小号":[["他吹小号的声音很动听。","ئۇنىڭ كىچىك سىرناي چالغان ئاۋازى بەك يېقىملىق.","uning kichik sirnay chalghan awazi bek yéqimliq."]],"小饭馆":[["这家小饭馆味道不错。","بۇ كىچىك ئاشخانىنىڭ تەمى يامان ئەمەس.","bu kichik ashxanining temi yaman emes."]],"小狮座":[["小狮座是南半球的一个星座。","كىچىك شىر يۇلتۇز تۈركۈمى جەنۇبىي يېرىم شارنىڭ بىر يۇلتۇز تۈركۈمى.","kichik shir yultuz türkümi jenubiy yérim sharning bir yultuz türkümi."]],"少年宫":[["少年宫是孩子们的活动场所。","ياشلار سارىيى بالىلارنىڭ پائالىيەت ئورنى.","yashlar sariyi balilarning paaliyet orni."]],"少男少女":[["少男少女对爱情充满好奇。","ياش ئوغۇل-قىزلار مۇھەببەتكە قىزىقىش بىلەن تولغان.","yash oghul-qizlar muhebbetke qiziqish bilen tolghan."]],"尼日尔河":[["尼日尔河是非洲西部的重要河流。","نىگېر دەرياسى ئافرىقىنىڭ غەربىي قىسمىدىكى مۇھىم دەريادۇر.","nigér deryasi afriqining gherbiy qismidiki muhim deryadur."]],"展宽":[["摄影师通过展宽视角捕捉更多细节。","فوتوگراف كۆرۈش دائىرىسىنى كەڭەيتىش ئارقىلىق تېخىمۇ كۆپ تەپسىلاتلارنى تۇتتى.","fotograf körüsh dairisini kengeytish arqiliq téximu köp tepsilatlarni tutti."]],"山峦重叠":[["山峦重叠，形成独特的景观。","شەنلۈەن بىر-بىرىگە قاتلىنىپ، ئۆزگىچە مەنزىرە شەكىللەندۈردى.","shenlüen bir-birige qatlinip, özgiche menzire shekillendürdi."]],"局促一隅":[["他局促一隅，不知所措。","ئۇ تار بىر بۇلۇڭدا قىسىلىپ، نېمە قىلىشىنى بىلەلمەي قالدى.","u tar bir bulungda qisilip, néme qilishini bilelmey qaldi."]],"山梨县":[["山梨县以苹果产业闻名。","شاڭلى ناھىيىسى ئالمىچىلىق كەسپى بىلەن داڭلىقتۇر.","shangli nahiyisi almichiliq kespi bilen dangliqtur."]],"山墙":[["山墙倒塌后，房屋变得危险。","تاغ تامى ئۆرۈلگەندىن كېيىن، ئۆي خەتەرلىك بولۇپ قالدى.","tagh tami örülgendin kéyin, öy xeterlik bolup qaldi."]],"山羊胡子":[["山羊胡子的形状很独特。","ئۆچكە ساقىلىنىڭ شەكلى ئىنتايىن ئالاھىدە.","öchke saqilining shekli intayin alahide."]],"岩壑":[["岩壑深处隐藏着古老的洞穴。","تاش جىلغىنىڭ چوڭقۇرىدا قەدىمىي ئۆڭكۈر يوشۇرۇنغان.","tash jilghining chongqurida qedimiy öngkür yoshurunghan."]],"岩屑":[["岩屑堆积在河流的沿岸。","تاش چاڭ-توزانى دەريا بويىدا توپلانغان.","tash chang-tozani derya boyida toplanghan."]],"岷江":[["岷江是长江的重要支流。","مىن دەرياسى يانگتسى دەرياسىنىڭ مۇھىم تارماق ئېقىنى.","min deryasi yangtsi deryasining muhim tarmaq éqini."]],"峨眉柳莺":[["峨眉柳莺叫声悦耳。","ئېمېي تال چىۋىقچىسىنىڭ ئاۋازى يېقىملىق.","éméy tal chiwiqchisining awazi yéqimliq."]],"崇文门":[["崇文门历史悠久。","چۇڭۋېنمېننىڭ تارىخى ئۇزۇن.","chungwénménning tarixi uzun."]],"崇祯":[["崇祯是明朝皇帝。","چۇڭجېن مىڭ سۇلالىسىنىڭ ئىمپېراتورى.","chungjén ming sulalisining impératori."]],"崎岖":[["山路崎岖难行。","تاغ يولى ئىگىز-تۆۋەن ۋە مېڭىشى قىيىن.","tagh yoli igiz-töwen we méngishi qiyin."]],"崖州":[["崖州是古代著名的流放之地。","يەيجۇ قەدىمكى زاماندىكى داڭلىق سۈرگۈن قىلىش جايى.","yeyju qedimki zamandiki dangliq sürgün qilish jayi."]],"工位":[["每个工位都有明确分工。","ھەر بىر ئىش ئورنىدا ئېنىق ئەمگەك تەقسىماتى بار.","her bir ish ornida éniq emgek teqsimati bar."]],"工伤假":[["他申请了工伤假进行休养。","ئۇ ئىش جەريانىدىكى زەخىمى ئۈچۈن دەم ئېلىش تەتىلىگە ئىلتىماس قىلدى.","u ish jeryanidiki zeximi üchün dem élish tetilige iltimas qildi."]],"工具人":[["他成了同事们的工具人。","ئۇ ھەمكارلارنىڭ قورالىغا ئايلاندى.","u hemkarlarning qoraligha aylandi."]],"岭𫶕":[["岭𫶕是连接两座山峰的山脊。","لىڭشىيا ئىككى تاغ چوققىسىنى تۇتاشتۇرىدىغان تاغ بېلى.","lingshiya ikki tagh choqqisini tutashturidighan tagh béli."]],"岱庙":[["岱庙是当地著名的景点。","دەيمىياۋ يەرلىكتىكى داڭلىق مەنزىرە نۇقتىسى.","deymiyaw yerliktiki dangliq menzire nuqtisi."]],"工具机":[["这台工具机操作起来很方便。","بۇ قورال ماشىنىسىنى مەشغۇلات قىلىش ئىنتايىن قولايلىق.","bu qoral mashinisini meshghulat qilish intayin qolayliq."]],"巨峰":[["巨峰葡萄口感甘美多汁。","گىگانت چوققا ئۈزۈمىنىڭ تەمى تاتلىق ۋە شىرەلىكتۇر.","gigant choqqa üzümining temi tatliq we shireliktur."]],"工种":[["工种指不同职业的具体分类。","ئىش تۈرى كەسىپلەرنىڭ تۈرلۈك ئېنىق تۈرگە بۆلۈنۈشىنى كۆرسىتىدۇ.","ish türi kesiplerning türlük éniq türge bölünüshini körsitidu."]],"布伦轻机枪":[["布伦轻机枪在战场上表现优异。","بۇرۇن يېنىك پۇشكا مەيداندا ئالاھىدە ياخشى نەتىجە كۆرسەتتى.","burun yénik pushka meydanda alahide yaxshi netije körsetti."]],"市郊":[["市郊的房价比市中心便宜许多。","شەھەر ئەتراپىدىكى ئۆي باھاسى شەھەر مەركىزىدىكىدىن خېلى ئەرزان.","sheher etrapidiki öy bahasi sheher merkizidikidin xéli erzan."]],"布朗尼":[["布朗尼是一种受欢迎的甜点。","برونىي ئالقىشقا ئېرىشكەن بىر خىل تاتلىق تائامدۇر.","broniy alqishqa érishken bir xil tatliq taamdur."]],"布洛陀":[["布洛陀是中国古代的神话人物。","بۇلووتو جۇڭگونىڭ قەدىمكى ئەپسانىۋى شەخسىدۇر.","bulooto junggoning qedimki epsaniwi shexsidur."]],"师姐":[["师姐指导我完成了项目。","ئاچا-سىڭىل ئوقۇتقۇچىم ماڭا تۈرنى تاماملىشىمغا يېتەكچىلىك قىلدى.","acha-singil oqutquchim manga türni tamamlishimgha yétekchilik qildi."]],"常在河边走，哪有不湿鞋":[["常在河边走，哪有不湿鞋，风险难免。","دائىم دەريا بويىدا ماڭسا، ئايىغى چىلانماسلىقى مۇمكىن ئەمەس، خەتەردىن قېچىپ قۇتۇلغىلى بولمايدۇ.","daim derya boyida mangsa, ayighi chilanmasliqi mumkin emes, xeterdin qéchip qutulghili bolmaydu."]],"帮凶":[["罪犯的帮凶最终被警方抓获。","جىنايەتچىنىڭ ياردەمچىسى ئاخىرىدا ساقچىلار تەرىپىدىن تۇتۇلدى.","jinayetchining yardemchisi axirida saqchilar teripidin tutuldi."]],"平叛":[["政府迅速平叛，恢复了社会秩序。","ھۆكۈمەت ئىسياننى تېز بېسىپ، جەمئىيەت تەرتىپىنى ئەسلىگە كەلتۈردى.","hökümet isyanni téz bésip, jem'iyet tertipini eslige keltürdi."]],"平均值":[["计算平均值需要所有数据。","ئوتتۇرىچە قىممەتنى ھېسابلاش ئۈچۈن بارلىق سانلىق مەلۇمات كېرەك.","otturiche qimmetni hésablash üchün barliq sanliq melumat kérek."]],"序号":[["请核对序号。","تەرتىپ نومۇرىنى سېلىشتۇرۇپ بېقىڭ.","tertip nomurini sélishturup béqing."]],"店长":[["店长负责管理整个店铺。","دۇكان باشلىقى پۈتۈن دۇكاننى باشقۇرۇشقا مەسئۇل.","dukan bashliqi pütün dukanni bashqurushqa mes'ul."]],"康有为":[["康有为是中国近代著名的思想家。","كاڭ يۇۋېي جۇڭگونىڭ يېقىنقى زامان مەشھۇر مۇتەپەككۇرى.","kang yuwéy junggoning yéqinqi zaman meshhur mutepekkuri."]],"康生":[["康生是中国共产党早期的领导人。","كاڭشېڭ جۇڭگو كوممۇنىستىك پارتىيىسىنىڭ دەسلەپكى رەھبەرلىرىدىن بىرى.","kangshéng junggo kommunistik partiyisining deslepki rehberliridin biri."]],"庸人自扰":[["庸人自扰是指自己给自己找麻烦。","ئادەتتىكى كىشى ئۆزىگە ئاۋارىچىلىق ئېلىپ كېلىشىنى كۆرسىتىدۇ.","adettiki kishi özige awarichiliq élip kélishini körsitidu."]],"广告宣传":[["广告宣传能有效提升品牌知名度。","ئېلان تەشۋىقاتى ماركا تونۇلۇشىنى ئۈنۈملۈك ئۆستۈرەلەيدۇ.","élan teshwiqati marka tonulushini ünümlük östüreleydu."]],"廿八躔":[["廿八躔是古代历法术语。","يىگىرمە سەككىز يۇلتۇز ئورنى قەدىمكى كالېندار ئاتالغۇسى.","yigirme sekkiz yultuz orni qedimki kaléndar atalghusi."]],"强求":[["强求别人只会适得其反。","باشقىلارنى كۈچ بىلەن تەلەپ قىلىش پەقەت تەتۈر نەتىجە بېرىدۇ.","bashqilarni küch bilen telep qilish peqet tetür netije béridu."]],"廊酒":[["廊酒是一种产自廊桥地区的酒。","لاڭجىۈ لاڭچياۋ رايونىدا ئىشلەپچىقىرىلغان بىر خىل ھاراق.","langjiü langchyaw rayonida ishlepchiqirilghan bir xil haraq."]],"彩民":[["彩民们期待着开奖结果。","Lotto بېلەت ئالغۇچىلار ئۇچۇر نەتىجىسىنى ئىنتىزارلىق بىلەن كۈتمەكتە.","Lotto bélet alghuchilar uchur netijisini intizarliq bilen kütmekte."]],"彩云":[["彩云在天空中缓缓飘动。","Rəڭلىك بۇلۇتلار ئاسماندا ئاستا لەيلەپ ماڭماقتا.","Rənglik bulutlar asmanda asta leylep mangmaqta."]],"待续":[["故事未完待续。","ھېكايە تېخى داۋاملىشىدۇ.","hékaye téxi dawamlishidu."]],"彩塑":[["这个彩塑作品充满艺术感。","بۇ رەڭدار سېلىنما ئەسەر سەنئەت تۇيغۇسىغا تولغان.","bu rengdar sélinma eser sen'et tuyghusigha tolghan."]],"徒步路径":[["这条徒步路径风景优美。","بۇ پىيادە مېڭىش يولىنىڭ مەنزىرىسى ئىنتايىن گۈزەل.","bu piyade méngish yolining menzirisi intayin güzel."]],"忘年交":[["他们成为忘年交，跨越年龄的界限。","ئۇلار يېشى پەرقلىق بولسىمۇ، ئۇنتۇلغۇسىز دوست بولۇپ قالدى.","ular yéshi perqliq bolsimu, untulghusiz dost bolup qaldi."]],"思情":[["他对她的思情一直难以释怀。","ئۇنىڭ ئۇنىڭغا بولغان سېغىنىش ھېسسىياتىدىن ھەرگىز قۇتۇلالماي كەلدى.","uning uninggha bolghan séghinish héssiyatidin hergiz qutulalmay keldi."]],"心平气和":[["面对冲突，他总能保持心平气和。","توقۇنۇشقا دۇچ كەلگەندە، ئۇ ھەمىشە كۆڭلى تىنچ ھالەتنى ساقلاپ قالالايدۇ.","toqunushqa duch kelgende, u hemishe köngli tinch haletni saqlap qalalaydu."]],"恒定":[["温度保持恒定，不会变化。","تېمپېراتۇرا تۇراقلىق ساقلىنىپ، ئۆزگەرمەيدۇ.","témpératura turaqliq saqlinip, özgermeydu."]],"性福":[["夫妻间的性福感能增进感情。","ئەر-خوتۇن ئارىسىدىكى جىنسىي بەخت-سائادەت تۇيغۇسى ئىجتىمائىي مۇناسىۋەتنى تېخىمۇ چوڭقۇرلاشتۇرىدۇ.","er-xotun arisidiki jinsiy bext-saadet tuyghusi ijtimaiy munasiwetni téximu chongqurlashturidu."]],"性蕾期":[["性蕾期是儿童性发育的重要阶段。","جىنسىي ئۆسۈش دەۋرى بالىلارنىڭ جىنسىي تەرەققىياتىنىڭ مۇھىم باسقۇچىدۇر.","jinsiy ösüsh dewri balilarning jinsiy tereqqiyatining muhim basquchidur."]],"心直嘴快":[["心直嘴快的人往往容易得罪他人。","ئېغىزى ئوچۇق كىشىلەر كۆپىنچە باشقىلارنىڭ كۆڭلىنى ئاسانلا قالدۇرىدۇ.","éghizi ochuq kishiler köpinche bashqilarning könglini asanla qalduridu."]],"恫吓":[["他用言语恫吓同事。","ئۇ سۆزلىرى بىلەن خىزمەتداشلىرىنى قورقۇتتى.","u sözliri bilen xizmetdashlirini qorqutti."]],"意气用事":[["他常常意气用事。","ئۇ كۆپىنچە ھېسسىياتىغا بېرىلىپ ئىش قىلىدۇ.","u köpinche héssiyatigha bérilip ish qilidu."]],"庆城":[["庆城是一座历史悠久的古城。","چىڭچېڭ ئۇزۇن تارىخقا ئىگە قەدىمىي شەھەردۇر.","chingchéng uzun tarixqa ige qedimiy sheherdur."]],"想望":[["他对成功充满想望。","ئۇ مۇۋەپپەقىيەتكە ئۈمىد باغلىغان.","u muweppeqiyetke ümid baghlighan."]],"宪章派":[["宪章派主张工人阶级团结。","ئاساسىي نىزام تەرەپدارلىرى ئىشچىلار سىنىپىنىڭ بىرلىكىنى تەشەببۇس قىلىدۇ.","asasiy nizam terepdarliri ishchilar sinipining birlikini teshebbus qilidu."]],"怜恤":[["他看到流浪猫时，总会心生怜恤，给它一些食物。","ئۇ سەرسان مۈشۈكنى كۆرگەندە، ھەمىشە ئىچى ئېچىشىپ، ئۇنىڭغا ئازراق ئوزۇق بېرىدۇ.","u sersan müshükni körgende, hemishe ichi échiship, uninggha azraq ozuq béridu."]],"凭单":[["购物时，请务必保留好凭单，以备查验。","خېرىدارلىق قىلغاندا، تەكشۈرۈشكە تەييارلىق قىلىش ئۈچۈن، چوقۇم تالوننى ياخشى ساقلاڭ.","xéridarliq qilghanda, tekshürüshke teyyarliq qilish üchün, choqum talonni yaxshi saqlang."]],"戳个儿":[["他戳个儿，想引起注意。","ئۇ دىققەت تارتىش ئۈچۈن تۆشۈك ئېچىپ باقتى.","u diqqet tartish üchün töshük échip baqti."]],"戳力":[["他使出了全身的戳力。","ئۇ پۈتۈن كۈچىنى ئىشلىتىپ تۆشۈك ئېچىشقا ئۇرۇندى.","u pütün küchini ishlitip töshük échishqa urundi."]],"我方":[["我方在谈判中占据了优势。","بىز سۆھبەتتە ئۈستۈنلۈككە ئىگە بولدۇق.","biz söhbette üstünlükke ige bolduq."]],"我曹":[["我曹，这真是不可思议！","ۋاي، بۇ ھەقىقەتەن ئىشەنگىلى بولمايدىغان ئىش!","way, bu heqiqeten ishengili bolmaydighan ish!"]],"戴秉国":[["戴秉国曾担任外交部长。","داي بىڭگو تاشقى ئىشلار مىنىستىرى بولۇپ ئىشلىگەن.","day binggo tashqi ishlar ministiri bolup ishligen."]],"手拉车":[["他用手拉车运了满满一车货物。","ئۇ قول ئارابىسى بىلەن تولۇق بىر ئارابا يۈك توشۇدى.","u qol arabisi bilen toluq bir araba yük toshudi."]],"打跟头":[["表演者打跟头十分精彩。","ئورۇنلىغۇچىنىڭ چەمبىرەك تاشلىشى ئىنتايىن ئېسىل ئىدى.","orunlighuchining chembirek tashlishi intayin ésil idi."]],"批荡":[["批荡是墙面处理的一种工艺。","پىداڭ تام بىر تەرەپ قىلىشنىڭ بىر خىل ھۈنەر-سەنئىتىدۇر.","pidang tam bir terep qilishning bir xil hüner-sen'itidur."]],"把酒":[["两人把酒言欢，畅聊往事。","ئىككىيلەن ھاراق ئىچىپ خۇشاللىشىپ، ئۆتمۈشلەرنى پاراڭلاشتى.","ikkiylen haraq ichip xushalliship, ötmüshlerni paranglashti."]],"抓去":[["敌人把俘虏抓去严刑拷打。","دۈشمەنلەر ئەسىرلەرنى تۇتۇپ ئېغىر جازالادى.","düshmenler esirlerni tutup éghir jazaladi."]],"承继":[["他承继了家族的传统技艺。","ئۇ ئائىلە ئەنئەنىۋى ھۈنىرىنى ۋارىسلىق قىلىپ ئالدى.","u aile en'eniwi hünirini warisliq qilip aldi."]],"拉丁文字":[["拉丁文字结构严谨。","لاتىن يېزىقىنىڭ قۇرۇلمىسى چىڭ.","latin yéziqining qurulmisi ching."]],"拙见":[["这只是拙见。","بۇ پەقەت مېنىڭ كۆز قارىشىم.","bu peqet méning köz qarishim."]],"拚财":[["拚财创业有风险。","پۇل خەجلەپ ئىش باشلاشتا خەتەر بار.","pul xejlep ish bashlashta xeter bar."]],"拉呱":[["他们坐在树下拉呱聊天。","ئۇلار دەرەخ ئاستىدا ئولتۇرۇپ پاراڭلىشىۋاتىدۇ.","ular derex astida olturup paranglishiwatidu."]],"招考":[["公司即将进行招考。","شىركەت يېقىندا ئىمتىھان ئېلىشنى ئېلىپ بارىدۇ.","shirket yéqinda imtihan élishni élip baridu."]],"招聘者":[["招聘者需要筛选简历。","خىزمەتچى قوبۇل قىلغۇچى تەرجىمىھالنى تاللىشى كېرەك.","xizmetchi qobul qilghuchi terjimihalni tallishi kérek."]],"拳打脚踢":[["坏人拳打脚踢，欺负弱小的人。","يامان كىشى مۇشتلاپ-تەپىپ، ئاجىزلارنى بوزەك قىلدى.","yaman kishi mushtlap-tepip, ajizlarni bozek qildi."]],"拳击台":[["拳击台是选手们竞技的舞台。","بوكس رىڭى توپچىلارنىڭ بەسلىشىدىغان سەھنىسى.","boks ringi topchilarning beslishidighan sehnisi."]],"拽步":[["他拖着疲惫的身体，缓慢地拽步前行。","ئۇ ھارغىن بەدىنىنى سۆرەپ، ئاستا-ئاستا قەدەم تاشلاپ ئىلگىرىلىدى.","u harghin bedinini sörep, asta-asta qedem tashlap ilgirilidi."]],"指环":[["这枚指环是祖传的古董。","بۇ بارماق ئۈزۈك ئەجدادلاردىن قالغان قىممەتلىك بۇيۇم.","bu barmaq üzük ejdadlardin qalghan qimmetlik buyum."]],"指甲钳":[["用指甲钳剪掉倒刺。","تىرناق ئېچىتقۇ بىلەن قىرتىلغان تىرناقنى كېسىڭ.","tirnaq échitqu bilen qirtilghan tirnaqni késing."]],"指路":[["他热情地为我们指路。","ئۇ بىزگە قىزغىنلىق بىلەن يول كۆرسەتتى.","u bizge qizghinliq bilen yol körsetti."]],"捆扎":[["工人正在捆扎建筑材料。","ئىشچىلار قۇرۇلۇش ماتېرىياللىرىنى باغلاۋاتىدۇ.","ishchilar qurulush matériyallirini baghlawatidu."]],"按摩师":[["按摩师的手法非常专业。","ماساژچىنىڭ ئۇسۇلى ئىنتايىن پ yetىشكەن.","masazhchining usuli intayin p yetishken."]],"扫墓":[["我们去扫墓。","بىز قەبرىستانلىققا بېرىپ تازىلىق قىلىمىز.","biz qebristanliqqa bérip taziliq qilimiz."]],"捧哏":[["他擅长捧哏表演。","ئۇ كۈلكىلىك دىئالوگ ئورۇنلاشتا ماھىر.","u külkilik dialog orunlashta mahir."]],"探矿者":[["探矿者发现了富含矿脉的岩层。","كان ئىزدىگۈچىلەر كان تومۇرىغا باي قاتلاملارنى بايقىدى.","kan izdigüchiler kan tomurigha bay qatlamlarni bayqidi."]],"推估":[["专家对经济形势进行了合理推估。","مۇتەخەسسىسلەر ئىقتىسادىي ئەھۋالغا مۇۋاپىق مۆلچەرلىدى.","mutexessisler iqtisadiy ehwalgha muwapiq mölcherlidi."]],"扬琴":[["扬琴是中国传统的弹拨乐器。","ياڭچىن جۇڭگونىڭ ئەنئەنىۋى چالغۇ ئەسۋابى.","yangchin junggoning en'eniwi chalghu eswabi."]],"握有":[["他握有重要的线索。","ئۇنىڭ قولىدا مۇھىم يىپ ئۇچى بار.","uning qolida muhim yip uchi bar."]],"挖洞":[["他们挖洞寻找地下水源。","ئۇلار ئورەك قېزىپ يەر ئاستى سۇ مەنبەسىنى ئىزدەيدۇ.","ular orek qézip yer asti su menbesini izdeydu."]],"揭底":[["他揭底了阴谋的真相。","ئۇ سۇيىقەستنىڭ ھەقىقىي يۈزىنى ئاشكارىلىدى.","u suyiqestning heqiqiy yüzini ashkarilidi."]],"搭咕":[["他们搭咕了一会儿。","ئۇلار بىردەم پاراڭلاشتى.","ular birdem paranglashti."]],"抠门":[["他平时非常抠门，不舍得花钱。","ئۇ ئادەتتە بەك خەسىس، پۇل سەرپ قىلىشقا ئۇنىمايدۇ.","u adette bek xesis, pul serp qilishqa unimaydu."]],"撒脚":[["他撒脚就跑，一刻也不停。","ئۇ دەرھال يۈگۈرۈپ كەتتى، بىر مىنۇتمۇ توختىمىدى.","u derhal yügürüp ketti, bir minutmu toxtimidi."]],"撞车":[["两辆车在路口撞车了。","ئىككى ماشىنا چاچىلىقتا سوقۇلدى.","ikki mashina chachiliqta soquldi."]],"撑船":[["他用竹竿撑船过河。","ئۇ بامبۇك تاياق بىلەن كېمىنى تىرەپ دەريادىن ئۆتتى.","u bambuk tayaq bilen kémini tirep deryadin ötti."]],"拟于不伦":[["这种搭配显得拟于不伦。","بۇ خىل ماسلىشىش تەقلىدىي ۋە مۇۋاپىقسىز كۆرۈنىدۇ.","bu xil maslishish teqlidiy we muwapiqsiz körünidu."]],"据我所知":[["据我所知，他明天会回来。","مېنىڭ بىلىشىمچە، ئۇ ئەتە قايتىپ كېلىدۇ.","méning bilishimche, u ete qaytip kélidu."]],"据我看":[["据我看，这个方案可行。","مېنىڭ قارىشىمچە، بۇ پىلان ئەمەلىيلەشتۈرۈشكە باب.","méning qarishimche, bu pilan emeliyleshtürüshke bab."]],"擦亮":[["他擦亮皮鞋，闪闪发光。","ئۇ تېرىسىنى يالتىراتتى، پارقىراپ تۇراتتى.","u térisini yaltiratti, parqirap turatti."]],"攀诬陷害":[["他们攀诬陷害。","ئۇلار يالغان ئەيىبلەپ تۆھمەت قىلدى.","ular yalghan eyiblep töhmet qildi."]],"攀谈":[["两人攀谈起来。","ئىككىيلەن سۆزلىشىپ كېتىشتى.","ikkiylen sözliship kétishti."]],"搀合":[["两种颜料搀合后颜色变了。","ئىككى خىل بوياق ئارىلاشتۇرۇلغاندىن كېيىن رەڭگى ئۆزگەردى.","ikki xil boyaq arilashturulghandin kéyin renggi özgerdi."]],"支店":[["这家支店规模较小。","بۇ تارماق دۇكاننىڭ كۆلىمى بىر قەدەر كىچىك.","bu tarmaq dukanning kölimi bir qeder kichik."]],"收尾":[["收尾工作已经完成，可以休息了。","ئاخىرقى ئىشلار تاماملاندى، ئارام ئالساق بولىدۇ.","axirqi ishlar tamamlandi, aram alsaq bolidu."]],"教堂山":[["教堂山是著名的旅游景点。","چېركاۋ تېغى داڭلىق ساياھەت نۇقتىسى.","chérkaw téghi dangliq sayahet nuqtisi."]],"教学法":[["这种教学法提高了效率。","بۇ خىل ئوقۇتۇش ئۇسۇلى ئۈنۈمنى ئۆستۈردى.","bu xil oqutush usuli ünümni östürdi."]],"教师爷":[["他被称为教师爷。","ئۇ ئوقۇتقۇچىلارنىڭ ئۇستازى دەپ ئاتىلىدۇ.","u oqutquchilarning ustazi dep atilidu."]],"故训":[["父亲的故训一直指引着我前行。","ئاتامنىڭ كونا تەلىمى ماڭا ھەمىشە يول كۆرسىتىپ كەلدى.","atamning kona telimi manga hemishe yol körsitip keldi."]],"摊晒":[["农民们将农作物摊晒在场上。","دېھقانلار يېزا ئىگىلىك مەھسۇلاتلىرىنى ئېتىزدا يېيىپ قۇرۇتتى.","déhqanlar yéza igilik mehsulatlirini étizda yéyip qurutti."]],"敌我矛盾":[["敌我矛盾是主要矛盾。","دۈشمەن بىلەن ئۆز ئارىسىدىكى زىددىيەت ئاساسلىق زىددىيەتتۇر.","düshmen bilen öz arisidiki ziddiyet asasliq ziddiyettur."]],"敞车":[["古代运输货物常用敞车。","قەدىمكى زاماندا يۈك توشۇشتا ئوچۇق ھارۋا كۆپ ئىشلىتىلەتتى.","qedimki zamanda yük toshushta ochuq harwa köp ishlitiletti."]],"数据集":[["研究人员整理了一个包含大量样本的数据集。","تەتقىقاتچىلار كۆپ مىقداردىكى ئۈلگىنى ئۆز ئىچىگە ئالغان بىر سانلىق مەلۇمات توپلىمىنى تەييارلىدى.","tetqiqatchilar köp miqdardiki ülgini öz ichige alghan bir sanliq melumat toplimini teyyarlidi."]],"数不清":[["这些礼物数也数不清。","بۇ سوۋغاتلارنى سانىغىلى بولمايدۇ.","bu sowghatlarni sanighili bolmaydu."]],"斑竹":[["这种斑竹的竹节上带有独特的花纹。","بۇ خىل داغلىق بامبۇكنىڭ بوغۇملىرىدا ئۆزگىچە نەقىش بار.","bu xil daghliq bambukning boghumlirida özgiche neqish bar."]],"斑纹":[["老虎身上的斑纹极具辨识度。","يولۋاسنىڭ بەدىنىدىكى داغلار ئىنتايىن ئېنىق پەرقلىنىدۇ.","yolwasning bedinidiki daghlar intayin éniq perqlinidu."]],"斑翅椋鸟":[["斑翅椋鸟成群结队地飞向远方。","تاغ تېكىسى چىۋىقىن قۇشى توپ-توپ بولۇپ يىراققا ئۇچىدۇ.","tagh tékisi chiwiqin qushi top-top bolup yiraqqa uchidu."]],"斯图加特":[["斯图加特以豪华汽车制造业闻名。","ستۇتگارت ھەشەمەتلىك ئاپتوموبىل ياساش سانائىتى بىلەن مەشھۇر.","stutgart heshemetlik aptomobil yasash sanaiti bilen meshhur."]],"斯坦顿":[["斯坦顿是女性权利运动的先驱者。","ستانتون ئايال ھوقۇقى ھەرىكىتىنىڭ ئالدىنقى قاتارىدىكىلەر.","stanton ayal hoquqi herikitining aldinqi qataridikiler."]],"斜交":[["两条直线可以斜交于一点。","ئىككى توغرا سىزىق بىر نۇقتىدا يانتاي شېرىيلىشەلەيدۇ.","ikki toghra siziq bir nuqtida yantay shériylisheleydu."]],"施以":[["公司施以严格的环保措施。","شىركەت قاتتىق مۇھىت قوغداش تەدبىرلىرىنى قوللاندى.","shirket qattiq muhit qoghdash tedbirlirini qollandi."]],"旬年":[["旬年相当于十年。","شۈننىيەن ئون يىلغا تەڭ.","shünniyen on yilgha teng."]],"易燃物品":[["厨房里有多种易燃物品。","ئاشخانىدا تۈرلۈك ئاسان يېنىدىغان بۇيۇملار بار.","ashxanida türlük asan yénidighan buyumlar bar."]],"明杖":[["明杖是一种古代的执法工具。","ئوپئوچاق قەدىمكى دەۋردىكى قانۇن ئىجرا قىلىش قورالى.","op'ochaq qedimki dewrdiki qanun ijra qilish qorali."]],"春日部":[["春日部是《蜡笔小新》的故乡。","كاسۇكابە «كرايون شىنچاڭ» نىڭ يۇرتى.","kasukabe «krayon shinchang» ning yurti."]],"易读":[["这本书非常易读。","بۇ كىتاب ئىنتايىن ئوقۇشقا ئاسان.","bu kitab intayin oqushqa asan."]],"时代广场":[["时代广场灯火辉煌。","زامان مەيدانى چىراغلار بىلەن جۇلالىنىپ كەتكەن.","zaman meydani chiraghlar bilen julalinip ketken."]],"普选权":[["普选权保障公民的参与。","ئومۇمىي سايلام ھوقۇقى پۇقرالارنىڭ قاتنىشىشىنى كاپالەتكە ئىگە قىلىدۇ.","omumiy saylam hoquqi puqralarning qatnishishini kapaletke ige qilidu."]],"景谷傣族彝族自治县":[["景谷傣族彝族自治县历史悠久。","جىڭگۇ دەي مىللىتى ۋە يى مىللىتى ئاپتونوم ناھىيىسىنىڭ تارىخى ئۇزۇندۇر.","jinggu dey milliti we yi milliti aptonom nahiyisining tarixi uzundur."]],"暗访":[["记者进行暗访调查。","مۇخبىر يوشۇرۇن زىيارەت تەكشۈرۈش ئېلىپ باردى.","muxbir yoshurun ziyaret tekshürüsh élip bardi."]],"会客":[["他经常在家中会客。","ئۇ دائىم ئۆيىدە مېھمان قوبۇل قىلىدۇ.","u daim öyide méhman qobul qilidu."]],"有潜力":[["他很有潜力，未来可期。","ئۇنىڭ ئىستىقبالى پارلاق، كەلگۈسى ئۈمىدلۈك.","uning istiqbali parlaq, kelgüsi ümidlük."]],"曲棍球":[["曲棍球是一项非常受欢迎的运动。","خوككېي ئىنتايىن ئالقىشقا ئېرىشكەن بىر تەنتەربىيە تۈرىدۇر.","xokkéy intayin alqishqa érishken bir tenterbiye türidur."]],"书皮":[["书皮可以保护书籍免受损坏。","كىتاب قېپى كىتابلارنى بۇزۇلۇشتىن قوغدايدۇ.","kitab qépi kitablarni buzulushtin qoghdaydu."]],"书目":[["这份书目列出了图书馆的全部藏书。","بۇ كىتاب تىزىملىكى كۇتۇپخانىنىڭ بارلىق كىتابلىرىنى تىزىپ كۆرسەتكەن.","bu kitab tizimliki kutupxanining barliq kitablirini tizip körsetken."]],"朗县":[["朗县风景优美。","لوڭ ناھىيىسىنىڭ مەنزىرىسى گۈزەل.","long nahiyisining menzirisi güzel."]],"有求必应":[["他为人有求必应，乐于助人。","ئۇ ھەر قانداق تەلەپكە ئىجابەت قىلىدىغان، ياردەمگە ئامراق كىشىدۇر.","u her qandaq telepke ijabet qilidighan, yardemge amraq kishidur."]],"朝鲜文":[["朝鲜文是朝鲜的主要官方语言。","چاۋشيەن تىلى چاۋشيەننىڭ ئاساسلىق رەسمىي تىلى.","chawshyen tili chawshyenning asasliq resmiy tili."]],"末梢神经":[["末梢神经受损会导致肢体麻木。","ئاخىرقى نېرۋا زەخىملىنىش ئەزالارنىڭ ھېسسىزلىنىشىگە سەۋەب بولىدۇ.","axirqi nérwa zeximlinish ezalarning héssizlinishige seweb bolidu."]],"未达一间":[["房间未达一间。","ئۆي بىر ئېغىزغا يەتمىدى.","öy bir éghizgha yetmidi."]],"李嘉欣":[["李嘉欣是一位国际影星。","لى كا شىن خەلقئارالىق كىنو چولپىنى.","li ka shin xelq'araliq kino cholpini."]],"本小利微":[["这个项目本小利微，但风险也不大。","بۇ تۈر ئاز پايدا ئېلىشى مۇمكىن، ئەمما خەۋپ-خەتىرىمۇ چوڭ ئەمەس.","bu tür az payda élishi mumkin, emma xewp-xetirimu chong emes."]],"东平县":[["东平县以豆腐闻名。","دۇڭپىڭ ناھىيىسى دوڭفۇ بىلەن ئاتاقلىق.","dungping nahiyisi dongfu bilen ataqliq."]],"东引乡":[["东引乡的渔获量很大。","دۇڭيىن يېزىسىنىڭ بېلىق تۇتۇش مىقدارى ئىنتايىن كۆپ.","dungyin yézisining béliq tutush miqdari intayin köp."]],"东城区":[["东城区有许多著名的古迹。","دۇڭچېڭ رايونىدا نۇرغۇن داڭلىق قەدىمكى ئورۇنلار بار.","dungchéng rayonida nurghun dangliq qedimki orunlar bar."]],"东至县":[["东至县历史悠久。","دۇڭجى ناھىيىسىنىڭ تارىخى ئۇزۇن.","dungji nahiyisining tarixi uzun."]],"林县":[["林县曾是著名的革命老区。","لىن شيەن ئىلگىرى مەشھۇر ئىنقىلابىي كونا رايون ئىدى.","lin shyen ilgiri meshhur inqilabiy kona rayon idi."]],"林西":[["林西的矿产资源储量十分丰富。","لىنشىنىڭ مېنىرال بايلىقلىرى ناھايىتى مول.","linshining méniral bayliqliri nahayiti mol."]],"杉山":[["杉山是日本的姓氏。","سۇگىياما ياپونىيەنىڭ بىر فامىلىسى.","sugiyama yaponiyening bir familisi."]],"东风区":[["东风区是武汉市的一个行政区。","دۇڭفېڭ رايونى ۋۇخەن شەھىرىدىكى بىر مەمۇرىي رايون.","dungféng rayoni wuxen shehiridiki bir memuriy rayon."]],"柯林":[["柯林是一名足球运动员。","كولىن بىر پۇتبولچىدۇر.","kolin bir putbolchidur."]],"架设":[["工人正在架设通信设备。","ئىشچىلار ئالاقە ئۈسكۈنىلىرىنى قۇرۇۋاتىدۇ.","ishchilar alaqe üskünilirini quruwatidu."]],"株洲":[["株洲是湖南省的一个城市。","جۇجۇ خۇنەن ئۆلكىسىدىكى بىر شەھەر.","juju xunen ölkisidiki bir sheher."]],"校草":[["校草是学校里最受欢迎的男生。","مەكتەپ چېچىكى مەكتەپتىكى ئەڭ مەشھۇر ئوغۇل ئوقۇغۇچىدۇر.","mektep chéchiki mekteptiki eng meshhur oghul oqughuchidur."]],"柴达木盆地":[["柴达木盆地位于青海省。","چەيدامۇ ئويمانلىقى چىڭخەي ئۆلكىسىدە جايلاشقان.","cheydamu oymanliqi chingxey ölkiside jaylashqan."]],"梅兰芳":[["梅兰芳是京剧大师。","مېيلەنفاڭ بېيجىڭ ئوپېراسىنىڭ ئۇستىسى.","méylenfang béyjing opérasining ustisi."]],"桑给巴尔":[["桑给巴尔是东非的岛屿国家。","زەنگىبار شەرقىي ئافرىقىدىكى ئارال دۆلىتى.","zengibar sherqiy afriqidiki aral döliti."]],"棉纱":[["工厂里正在纺制细腻的棉纱。","زاۋۇتتا نەپىس پاختا يىپ ئېگىلىۋاتىدۇ.","zawutta nepis paxta yip égiliwatidu."]],"森然":[["他神情森然，令人敬畏。","ئۇنىڭ چىرايىدا سوغۇق ھەيۋە بار، كىشىنى ھۆرمەت بىلەن قورقۇتىدۇ.","uning chirayida soghuq heywe bar, kishini hörmet bilen qorqutidu."]],"栖霞":[["栖霞的风景十分迷人。","شىشيا مەنزىرىسى ئىنتايىن جەلپكار.","shishya menzirisi intayin jelpkar."]],"棠梨":[["棠梨是一种常见的水果。","تاڭلى ئومۇميۈزلۈك بىر خىل مېۋە.","tangli omumyüzlük bir xil méwe."]],"棕背田鸡":[["这种棕背田鸡叫声清脆。","بۇ خىل قوڭۇر دۈمبىلىك سۇ توخۇسىنىڭ سايرىشى ئېنىق ھەم يېقىملىق.","bu xil qongur dümbilik su toxusining sayrishi éniq hem yéqimliq."]],"楠木":[["楠木是一种珍贵的木材。","نەنمۇ قىممەتلىك بىر خىل ياغاچتۇر.","nenmu qimmetlik bir xil yaghachtur."]],"桥接器":[["桥接器能扩展网络覆盖。","كۆۋرۈكلىگۈچ تور قاپلىمىنى كېڭەيتەلەيدۇ.","köwrükligüch tor qaplimini kéngeyteleydu."]],"橙汁":[["这杯橙汁味道非常清新爽口。","بۇ ئاپېلسىن شىرنىسىنىڭ تەمى ناھايىتى تازا ۋە يېقىملىق.","bu apélsin shirnisining temi nahayiti taza we yéqimliq."]],"枪林箭雨":[["战场上枪林箭雨，异常激烈。","مەيداندا ئوق يامغۇرى ۋە ئوقيا يامغۇرى ناھايىتى شىددەتلىك.","meydanda oq yamghuri we oqya yamghuri nahayiti shiddetlik."]],"次方言":[["次方言与当地文化相关。","كىچىك شېۋە يەرلىك مەدەنىيەت بىلەن مۇناسىۋەتلىك.","kichik shéwe yerlik medeniyet bilen munasiwetlik."]],"树根":[["树根深深扎在土壤里。","دەرەخ يىلتىزلىرى تۇپراققا چوڭقۇر يېيىلغان.","derex yiltizliri tupraqqa chongqur yéyilghan."]],"歇息":[["该歇息了，早点休息吧。","ئارام ئېلىش ۋاقتى بولدى، بالدۇرراق ئارام ئالغىن.","aram élish waqti boldi, baldurraq aram alghin."]],"欧式":[["这套家具是欧式风格。","بۇ ئۆي جاھازىسى ياۋروپا ئۇسلۇبىدا.","bu öy jahazisi yawropa uslubida."]],"欧氏":[["欧氏定理在数学中广泛应用。","ياۋروپا تېئورېمىسى ماتېماتىكىدا كەڭ قوللىنىلىدۇ.","yawropa téorémisi matématikida keng qollinilidu."]],"正反两面":[["问题有正反两面。","مەسىلىنىڭ مۇسبەت ۋە سەلبىي ئىككى تەرىپى بار.","mesilining musbet we selbiy ikki teripi bar."]],"正事":[["现在该谈正事了。","ئەمدى ئەسلىي ئىشقا كېلىشەيلى.","emdi esliy ishqa kélisheyli."]],"正锋":[["正锋笔触细腻。","تۈز ئۇچلۇق قەلەمنىڭ سىزىقى نەپىس.","tüz uchluq qelemning siziqi nepis."]],"正月初一":[["正月初一是农历新年的第一天。","جېڭيۈە چۈشى قەمەرىي يىلنىڭ يېڭى يىلنىڭ بىرىنچى كۈنىدۇر.","jéngyüe chüshi qemeriy yilning yéngi yilning birinchi künidur."]],"正多面体":[["正多面体结构稳定。","تىپىك كۆپ تەرەپلىك گەۋدە قۇرۇلمىسى مۇقىم.","tipik köp tereplik gewde qurulmisi muqim."]],"正定县":[["正定县以古寺和古城闻名。","جېڭدىڭ ناھىيىسى قەدىمىي ئىبادەتخانا ۋە قەدىمىي شەھەر بىلەن داڭلىق.","jéngding nahiyisi qedimiy ibadetxana we qedimiy sheher bilen dangliq."]],"杀人狂":[["那个杀人狂连续杀害了多人。","ئۇ ئۆلتۈرۈش ساراڭى ئارقا-ئارقىدىن نۇرغۇن كىشىنى ئۆلتۈردى.","u öltürüsh sarangi arqa-arqidin nurghun kishini öltürdi."]],"每端口价格":[["这款设备的每端口价格十分合理。","بۇ ئۈسكۈنىنىڭ ھەر بىر پورتىنىڭ باھاسى ئىنتايىن مۇۋاپىق.","bu üskünining her bir portining bahasi intayin muwapiq."]],"民族学":[["民族学研究不同文化的起源。","مىللەتشۇناسلىق ئوخشاش بولمىغان مەدەنىيەتلەرنىڭ كېلىپ چىقىشىنى تەتقىق قىلىدۇ.","milletshunasliq oxshash bolmighan medeniyetlerning kélip chiqishini tetqiq qilidu."]],"民族舞蹈":[["民族舞蹈展现了独特的文化魅力。","مىللەت ئۇسسۇلى ئۆزگىچە مەدەنىيەت جەلپكارلىقىنى نامايان قىلىدۇ.","millet ussuli özgiche medeniyet jelpkarliqini namayan qilidu."]],"残害":[["敌人残害了无数无辜的平民。","دۈشمەن سان-سىقىمسىز گۇناھسىز پۇقرالارنى زىيانكەشلىك قىلدى.","düshmen san-siqimsiz gunahsiz puqralarni ziyankeshlik qildi."]],"殷墟":[["殷墟是殷商时期的都城遗址。","يىن خارابىسى يىن شاڭ دەۋرىنىڭ پايتەخت خارابىسى.","yin xarabisi yin shang dewrining paytext xarabisi."]],"毛子国":[["毛子国的文化很有特色。","ماۋزى دۆلىتىنىڭ مەدەنىيىتى ئالاھىدە ئالاھىدىلىككە ئىگە.","mawzi dölitining medeniyiti alahide alahidilikke ige."]],"氧乙炔焊":[["氧乙炔焊是常见的金属焊接方法。","ئوكسىگېن-ئاستىلېن پەيۋەتلەش ئادەتتىكى مېتال پەيۋەتلەش ئۇسۇلىدۇر.","oksigén-astilén peywetlesh adettiki métal peywetlesh usulidur."]],"氢氧化钙":[["氢氧化钙可用来改良土壤。","ھىدروگېن-ئوكسىدلانغان كالتسىي تۇپراقنى ياخشىلاشتا ئىشلىتىلىدۇ.","hidrogén-oksidlanghan kaltsiy tupraqni yaxshilashta ishlitilidu."]],"氰酸":[["氰酸是一种强酸，具有腐蚀性。","سيان كىسلاتا كۈچلۈك كىسلاتا بولۇپ، كورروزىيەلىك خۇسۇسىيەتكە ئىگە.","syan kislata küchlük kislata bolup, korroziyelik xususiyetke ige."]],"氰酸盐":[["氰酸盐在工业中有广泛应用。","سيانات ئىندۇسترىيەدە كەڭ قوللىنىلىدۇ.","syanat industriyede keng qollinilidu."]],"水行侠":[["水行侠是武侠小说中的角色。","سۇ قەھرىمانى ۋۇشيا رومانلىرىدىكى بىر رول.","su qehrimani wushya romanliridiki bir rol."]],"水凼":[["水凼是指地面因积水而形成的凹陷区域。","سۇ كۆلچىكى يەر يۈزىدە سۇ يىغىلىشىدىن ھاسىل بولغان چۆكۈش رايونىنى كۆرسىتىدۇ.","su kölchiki yer yüzide su yighilishidin hasil bolghan chöküsh rayonini körsitidu."]],"永福县":[["永福县是福建省的一个县城。","يۇڭفۇ ناھىيىسى فۇجيەن ئۆلكىسىدىكى بىر ناھىيە.","yungfu nahiyisi fujyen ölkisidiki bir nahiye."]],"永诀":[["这次离别可能是永诀。","بۇ قېتىملىق ئايرىلىش مەڭگۈلۈك ئايرىلىش بولۇشى مۇمكىن.","bu qétimliq ayrilish menggülük ayrilish bolushi mumkin."]],"求告":[["他向官府求告冤情。","ئۇ ھۆكۈمەت ئورگىنىدىن ئەرىزىنى ئېيتىپ داد تىلىدى.","u hökümet orginidin erizini éytip dad tilidi."]],"沙白喉林莺":[["沙白喉林莺是一种珍稀鸟类。","شابەيخولىن پەسىتى ناھايىتى كام ئۇچرايدىغان بىر خىل قۇش.","shabeyxolin pesiti nahayiti kam uchraydighan bir xil qush."]],"沙河市":[["沙河市位于河南省。","شاھېشەھىرى خېنەن ئۆلكىسىدە جايلاشقان.","shahéshehiri xénen ölkiside jaylashqan."]],"油污":[["地板上有明显的油污。","پولدا ئېنىق يېغ كىرى بار.","polda éniq yégh kiri bar."]],"油泡":[["锅中出现了许多油泡。","قازاندا نۇرغۇن ماي كۆپۈكلىرى پەيدا بولدى.","qazanda nurghun may köpükliri peyda boldi."]],"泉山":[["泉山是著名的旅游胜地。","چۈەنشەن تېغى داڭلىق ساياھەت جايى.","chüenshen téghi dangliq sayahet jayi."]],"油鸡":[["油鸡是一种经过特殊饲养的鸡肉品种。","ماي توخۇسى ئالاھىدە بېقىلغان توخۇ گۆشى تۈرىدۇر.","may toxusi alahide béqilghan toxu göshi türidur."]],"泗县":[["泗县是安徽省的一个县。","سىشيەن ئەنخۇي ئۆلكىسىدىكى بىر ناھىيە.","sishyen enxuy ölkisidiki bir nahiye."]],"泥古不化":[["他泥古不化，拒绝接受新事物。","ئۇ كونا چۈشەنچىلەردە چىڭ تۇرۇپ، يېڭى نەرسىلەرنى قوبۇل قىلىشنى رەت قىلىدۇ.","u kona chüshenchilerde ching turup, yéngi nersilerni qobul qilishni ret qilidu."]],"洞察一切":[["他似乎能够洞察一切事物的本质。","ئۇ ھەممە ئىشنىڭ ماھىيىتىنى چۈشىنىپ يېتەلەيدىكەن.","u hemme ishning mahiyitini chüshinip yételeydiken."]],"海损":[["海损是指海上运输中的损失。","دېڭىز زىيىنى دېڭىز توشۇشتىكى زىياننى كۆرسىتىدۇ.","déngiz ziyini déngiz toshushtiki ziyanni körsitidu."]],"海星":[["海星是一种生活在海底的星形动物。","دېڭىز يۇلتۇزى دېڭىز تەگلىكىدە ياشايدىغان يۇلتۇز شەكىللىك ھايۋان.","déngiz yultuzi déngiz teglikide yashaydighan yultuz shekillik haywan."]],"海星机场":[["海星机场位于城市的东部。","دېڭىز يۇلتۇزى ئايرودرومى شەھەرنىڭ شەرقىي قىسمىدا.","déngiz yultuzi ayrodromi sheherning sherqiy qismida."]],"海沟":[["海沟是地壳中深邃的凹陷地带。","دېڭىز ئاستى ئېرىقى يەر پوستىدىكى چوڭقۇر چۆكۈش زېمىنىدۇر.","déngiz asti ériqi yer postidiki chongqur chöküsh zéminidur."]],"消防署":[["消防署接到报警后立刻出动了。","ئوت ئۆچۈرۈش ئىدارىسى ئاگاھلاندۇرۇش ئالغاندىن كېيىن دەرھال ئاتلاندى.","ot öchürüsh idarisi agahlandurush alghandin kéyin derhal atlandi."]],"泪液":[["泪液在眼眶中逐渐聚集。","كۆز ئىچىدە ياش ئاستا-ئاستا جەم بولۇۋاتىدۇ.","köz ichide yash asta-asta jem boluwatidu."]],"清热":[["这款饮品有清热解暑的功效。","بۇ ئىچىملىكنىڭ ئىسسىقنى چىقىرىش ۋە ياز ئىسسىقىنى يېنىكلىتىش ئۈنۈمى بار.","bu ichimlikning issiqni chiqirish we yaz issiqini yéniklitish ünümi bar."]],"涡虫纲":[["涡虫纲属于扁形动物门。","تۈرۈبىلىق قۇرتلار تۈرى ياپىلاق جانلىقلار تىپىغا تەۋەدۇر.","türübiliq qurtlar türi yapilaq janliqlar tipigha tewedur."]],"减价":[["这件商品正在减价促销。","بۇ مەھسۇلات باھاسى تۆۋەنلىتىلىپ سېتىلماقتا.","bu mehsulat bahasi töwenlitilip sétilmaqta."]],"港北":[["港北是城市的一个区域。","گاڭبېي شەھەرنىڭ بىر رايونى.","gangbéy sheherning bir rayoni."]],"港南":[["港南是城市的重要区域。","گاڭنەن شەھەرنىڭ مۇھىم رايونى.","gangnen sheherning muhim rayoni."]],"港口城市":[["港口城市通常经济发达。","پورت شەھەرلىرى ئادەتتە ئىقتىسادىي جەھەتتىن تەرەققىي قىلغان.","port sheherliri adette iqtisadiy jehettin tereqqiy qilghan."]],"海鸟":[["海鸟在天空中飞翔。","دېڭىز قۇشلىرى ئاسماندا ئۇچىدۇ.","déngiz qushliri asmanda uchidu."]],"海龟":[["海龟在海洋中缓慢游动。","دېڭىز تاشپاقىسى دېڭىزدا ئاستا ئۈزىدۇ.","déngiz tashpaqisi déngizda asta üzidu."]],"溪口乡":[["溪口乡位于山区。","شىكۇ يېزىسى تاغلىق رايوندا جايلاشقان.","shiku yézisi taghliq rayonda jaylashqan."]],"温网":[["温网比赛今天正式开赛。","ۋىمبىلدون مۇسابىقىسى بۈگۈن رەسمىي باشلاندى.","wimbildon musabiqisi bügün resmiy bashlandi."]],"沪宁线":[["沪宁线连接上海和南京。","خۇنىڭ لىنىيەسى شاڭخەي بىلەن نەنجىڭنى تۇتاشتۇرىدۇ.","xuning liniyesi shangxey bilen nenjingni tutashturidu."]],"汉密尔顿":[["汉密尔顿是著名的美国开国元勋。","خەنمىلتون ئامېرىكىنىڭ داڭلىق قۇرغۇچى ئاتىسى.","xenmilton amérikining dangliq qurghuchi atisi."]],"漂泊":[["他漂泊多年，无家可归。","ئۇ كۆپ يىللاردىن بېرى سەرسان بولۇپ، ئۆيى يوق.","u köp yillardin béri sersan bolup, öyi yoq."]],"涨到":[["油价已经涨到每升十元。","ماي باھاسى ھەر لىتىرى ئون يۈەنگە قەدەر ئۆستى.","may bahasi her litiri on yüenge qeder östi."]],"涨姿势":[["这个视频让我涨姿势不少。","بۇ سىن ماڭا ناھايىتى كۆپ بىلىم ئۆستۈردى.","bu sin manga nahayiti köp bilim östürdi."]],"渐行渐远":[["他们渐行渐远，最终消失在视野中。","ئۇلار تەدرىجىي يىراقلىشىپ، ئاخىرىدا كۆز ئالدىدىن غايىب بولدى.","ular tedrijiy yiraqliship, axirida köz aldidin ghayib boldi."]],"渐变":[["天空的颜色逐渐变化，从蓝转为橙。","ئاسماننىڭ رەڭگى تەدرىجىي ئۆزگىرىپ، كۆكتىن قىزغۇچ سېرىققا ئايلاندى.","asmanning renggi tedrijiy özgirip, köktin qizghuch sériqqa aylandi."]],"潭底":[["潭底有许多古老的石头。","كۆلچەك تۈۋىدە نۇرغۇن قەدىمىي تاشلار بار.","kölchek tüwide nurghun qedimiy tashlar bar."]],"滨田":[["滨田是一位著名的日本摄影师。","بىنتيەن تونۇلغان ياپونىيەلىك فوتوگراف.","bintyen tonulghan yaponiyelik fotograf."]],"火德星君":[["火德星君是中国神话中的火神。","ئوت پەرىشتىسى جۇڭگو ئەپسانىلىرىدىكى ئوت تەڭرىسىدۇر.","ot perishtisi junggo epsaniliridiki ot tengrisidur."]],"火成碎屑":[["火成碎屑是火山喷发产生的物质。","ئوت پارچىلىرى يانار تاغ ئېتىلىشىدىن ھاسىل بولىدىغان ماددىلاردۇر.","ot parchiliri yanar tagh étilishidin hasil bolidighan maddilardur."]],"澎湖":[["澎湖是台湾著名的旅游胜地。","پېڭخۇ تەيۋەننىڭ مەشھۇر ساياھەت جايى.","péngxu teywenning meshhur sayahet jayi."]],"乌兰巴托":[["乌兰巴托是蒙古国的首都。","ئۇلانباتور موڭغۇلىيەنىڭ پايتەختىدۇر.","ulanbator mongghuliyening paytextidur."]],"乌达区":[["乌达区是乌达市的一个行政区。","ئۇدا رايونى ئۇدا شەھىرىدىكى بىر مەمۇرىي رايونتۇر.","uda rayoni uda shehiridiki bir memuriy rayontur."]],"乌德勒支":[["乌德勒支是荷兰的一座历史文化名城。","ئۇترېخت نىدېرلاندىيەدىكى بىر تارىخىي-مەدەنىي شەھەردۇر.","utréxt nidérlandiyediki bir tarixiy-medeniy sheherdur."]],"乌鲁汝":[["乌鲁汝是当地的一种植物。","ئۇلۇرۇش بۇ يەرنىڭ بىر خىل ئۆسۈملۈكى.","ulurush bu yerning bir xil ösümlüki."]],"烙铁":[["烙铁加热后用来烫布。","دەملەك تۆمۈرنى قىزىتقاندىن كېيىن رەخت بېسىشقا ئىشلىتىدۇ.","demlek tömürni qizitqandin kéyin rext bésishqa ishlitidu."]],"无用":[["这个建议毫无用处。","بۇ تەكلىپ پۈتۈنلەي پايدىسىز.","bu teklip pütünley paydisiz."]],"无的放矢":[["批评不能无的放矢。","تەنقىد نىشانسىز بولۇشقا بولمايدۇ.","tenqid nishansiz bolushqa bolmaydu."]],"无轨":[["这种交通工具是无轨电车。","بۇ قاتناش قورالى رېلىسسىز ترامۋاي.","bu qatnash qorali rélissiz tramway."]],"烟花场":[["烟花场里人山人海，气氛热烈。","ئاتەش ئويۇنى مەيدانى ئادەم بىلەن تولۇپ، كەيپىيات قىزغىن.","atesh oyuni meydani adem bilen tolup, keypiyat qizghin."]],"烟花行院":[["烟花行院曾是艺人聚集的地方。","ئاتەش ئويۇنى ۋە سېرىق ئۆيلەر ئىلگىرى سەنئەتكارلار توپلانغان جاي ئىدى.","atesh oyuni we sériq öyler ilgiri sen'etkarlar toplanghan jay idi."]],"烫头发":[["她决定去理发店烫头发。","ئۇ چاچ ئالمىلىق دۇكانغا بېرىپ چېچىنى دەملەشكە قارار قىلدى.","u chach almiliq dukangha bérip chéchini demleshke qarar qildi."]],"牛心":[["牛心是牛的心脏部位。","كالا يۈرىكى كالا يۈرىكىنىڭ قىسمى.","kala yüriki kala yürikining qismi."]],"牛痘病":[["牛痘病在历史上曾造成大量死亡。","كالا چېچەك كېسىلى تارىختا كۆپ ئۆلۈمگە سەۋەب بولغان.","kala chéchek késili tarixta köp ölümge seweb bolghan."]],"燕国":[["燕国是古代的一个诸侯国。","يەن دۆلىتى قەدىمكى زاماندىكى بىر ۋىلايەت دۆلىتى ئىدى.","yen döliti qedimki zamandiki bir wilayet döliti idi."]],"争论点":[["争论点在于政策的具体实施细节。","تالاش-تارتىش نۇقتىسى سىياسەتنىڭ كونكرېت ئىجرا تەپسىلاتىدا.","talash-tartish nuqtisi siyasetning konkrét ijra tepsilatida."]],"特洛伊":[["特洛伊是古代著名的城市之一。","ترويا قەدىمدىكى مەشھۇر شەھەرلەرنىڭ بىرىدۇر.","troya qedimdiki meshhur sheherlerning biridur."]],"猛吃":[["他饿得猛吃一大碗饭。","ئۇ ئاچلىقتىن كۈچ بىلەن بىر چوڭ قاچا تاماق يېدى.","u achliqtin küch bilen bir chong qacha tamaq yédi."]],"珍馐美味":[["宴席上摆满了珍馐美味。","زىياپەتتە نەپىس تائاملار تىزىلغان.","ziyapette nepis taamlar tizilghan."]],"玉米棒":[["玉米棒是农民辛勤劳动的成果。","مەككەجۆۋەرى كالتىكى دېھقانلارنىڭ جاپالىق ئەمگىكىنىڭ نەتىجىسى.","mekkejöweri kaltiki déhqanlarning japaliq emgikining netijisi."]],"兽医学":[["兽医学研究动物健康。","مال دوختۇرلۇق ئىلمى ھايۋانلارنىڭ ساغلاملىقىنى تەتقىق قىلىدۇ.","mal doxturluq ilmi haywanlarning saghlamliqini tetqiq qilidu."]],"玉山":[["玉山是著名的旅游胜地。","يۈشەن داڭلىق ساياھەت جايىدۇر.","yüshen dangliq sayahet jayidur."]],"环境卫生":[["保持环境卫生是健康基础。","مۇھىت تازالىقىنى ساقلاش ساغلاملىقنىڭ ئاساسى.","muhit tazaliqini saqlash saghlamliqning asasi."]],"瓶鼻海豚":[["瓶鼻海豚生活在海洋中。","بوتۇلكا بۇرنىلۇق دېلفىن دېڭىزدا ياشايدۇ.","botulka burniluq délfin déngizda yashaydu."]],"瑙鲁":[["瑙鲁是太平洋上的一个小岛国。","ناۋرۇ تىنچ ئوكياندىكى كىچىك بىر ئارال دۆلىتى.","nawru tinch okyandiki kichik bir aral döliti."]],"甲胺":[["甲胺是一种有机化合物。","جيامىن بىر خىل ئورگانىك بىرىكمە.","jyamin bir xil organik birikme."]],"产业工人":[["产业工人是推动发展的力量。","سانائەت ئىشچىلىرى تەرەققىياتنى ئىلگىرى سۈرىدىغان كۈچ.","sanaet ishchiliri tereqqiyatni ilgiri süridighan küch."]],"毕命":[["他毕命于这场战役。","ئۇ بۇ جەڭدە ھاياتىنى بەخت قىلدى.","u bu jengde hayatini bext qildi."]],"疑问句":[["这是一个带有疑问句的提问。","بۇ سوئال جۈملىسى بار سوئالدۇر.","bu soal jümlisi bar soaldur."]],"疑点":[["报告中存在几个疑点。","دوكلاتتا بىر قانچە گۇمانلىق نۇقتا بار.","doklatta bir qanche gumanliq nuqta bar."]],"发迹":[["他凭借才华在业界迅速发迹。","ئۇ تالانتىغا تايىنىپ كەسىپتە تېزلا داڭق چىقاردى.","u talantigha tayinip kesipte tézla dangq chiqardi."]],"白领翡翠":[["白领翡翠羽毛鲜艳亮丽。","ئاق ياقىلىق كۆك ياقۇت قۇشىنىڭ پەيلىرى پارقىراپ چىرايلىق.","aq yaqiliq kök yaqut qushining peyliri parqirap chirayliq."]],"白粥":[["生病时喝一碗白粥很舒服。","كېسەل بولغاندا بىر چىنە ئاق ئۇماچ ئىچسە راھەت.","késel bolghanda bir chine aq umach ichse rahet."]],"白翅交嘴雀":[["白翅交嘴雀的羽毛颜色鲜艳。","ئاق قاناتلىق كاۋاك قۇشىنىڭ پەيلىرىنىڭ رەڭگى پارقىراق.","aq qanatliq kawak qushining peylirining renggi parqiraq."]],"矽肺病":[["矽肺病需要长期治疗。","شىجىڭ ئۆپكە كېسەللىكى ئۇزۇن مۇددەتلىك داۋالاشنى تەلەپ قىلىدۇ.","shijing öpke késelliki uzun muddetlik dawalashni telep qilidu."]],"短耳鸮":[["短耳鸮是夜间活动的鸟类。","قىسقا قۇلاقلىق ئۈكۈ كېچىدە پائالىيەت قىلىدىغان قۇش.","qisqa qulaqliq ükü kéchide paaliyet qilidighan qush."]],"石斛":[["石斛是一种具有药用价值的植物。","شىخۇ بولسا دورىلىق قىممەتكە ئىگە بىر خىل ئۆسۈملۈك.","shixu bolsa doriliq qimmetke ige bir xil ösümlük."]],"笑纹":[["眼角的笑纹见证了她的快乐。","كۆز قىرلىرىدىكى كۈلۈش ئىزلىرى ئۇنىڭ خۇشاللىقىنى ئىسپاتلايدۇ.","köz qirliridiki külüsh izliri uning xushalliqini ispatlaydu."]],"竹管":[["竹管常用于制作简易乐器。","بامبۇك تۇرۇبىسى ئاددىي چالغۇلارنى ياساشتا كۆپ ئىشلىتىلىدۇ.","bambuk turubisi addiy chalghularni yasashta köp ishlitilidu."]],"细胞器官":[["细胞器官由多种细胞器协同工作组成。","ھۈجەيرە ئورگانلىرى كۆپ خىل ھۈجەيرە ئورگانىدىلىرىنىڭ ھەمكارلىشىشىدىن تەركىب تاپىدۇ.","hüjeyre organliri köp xil hüjeyre organidilirining hemkarlishishidin terkib tapidu."]],"细胞因子":[["细胞因子能调节免疫系统的反应。","ھۈجەيرە سىيتوكىنلىرى ئىممۇنىتېت سىستېمىسىنىڭ ئىنكاسىنى تەڭشىيەلەيدۇ.","hüjeyre siytokinliri immunitét sistémisining inkasini tengshiyeleydu."]]};
